(window.__ATLAS_DATA=window.__ATLAS_DATA||{})["data/acts/L106.json"]={"meta":{"id":"L106","name":"Legea privind asigurarea obligatorie de răspundere civilă auto","short":"Legea nr. 106/2022","type":"Lege","number":"106/2022","date":"21.04.2022","published":"Publicat : 29.04.2022 în MONITORUL OFICIAL Nr. 129-133 art. 239 Data intrării în vigoare","lastAmend":"LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25","aliases":["lege:106/2022"],"titleRaw":"privind asigurarea obligatorie de răspundere civilă auto pentru pagube produse de vehicule","signature":["PREȘEDINTELE PARLAMENTULUI Igor GROSU","Nr. 106. Chișinău, 21 aprilie 2022."],"preamble":["MODIFICAT","LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25","Parlamentul adoptă prezenta lege organică.","Prezenta lege transpune:","– parțial Directiva 2009/103/CE a Parlamentului European și a Consiliului din 16 septembrie 2009 privind asigurarea de răspundere civilă auto și controlul obligației de asigurare a acestei răspunderi (text cu relevanță pentru SEE), publicată în Jurnalul Oficial al Uniunii Europene L 263 din 7 octombrie 2009;","– art.21 alin.(2) și art. 181 alin. (3) din Directiva 2009/138/CE a Parlamentului European și a Consiliului din 25 noiembrie 2009 privind accesul la activitate și desfășurarea activității de asigurare și de reasigurare (Solvabilitate II) (text cu relevanță pentru SEE), publicată în Jurnalul Oficial al Uniunii Europene L 335 din 17 decembrie 2009, așa cum a fost modificată ultima oară prin Directiva (UE) 2018/843 a Parlamentului European și a Consiliului din 30 mai 2018 de modificare a Directivei (UE) 2015/849 privind prevenirea utilizării sistemului financiar în scopul spălării banilor sau finanțării terorismului, precum și de modificare a Directivelor 2009/138/CE și 2013/36/UE, publicată în Jurnalul Oficial al Uniunii Europene L 156/43 din 19 iunie 2018."]},"nodes":[{"id":"n1","kind":"capitol","lvl":3,"label":"Capitolul I","name":"DISPOZIȚII GENERALE","parent":null,"arts":[]},{"id":"n2","kind":"sectiune","lvl":4,"label":"Secțiunea 1","name":"Obiectul și domeniul de aplicare a legii","parent":"n1","arts":["1","2","3","4","5","6","7"]},{"id":"n3","kind":"sectiune","lvl":4,"label":"Secțiunea a 2-a","name":"Contractul de asigurare obligatorie de răspundere civilă auto","parent":"n1","arts":["8","9","10","11"]},{"id":"n4","kind":"capitol","lvl":3,"label":"Capitolul II","name":"ASIGURAREA OBLIGATORIE DE RĂSPUNDERE CIVILĂ AUTO","parent":null,"arts":[]},{"id":"n5","kind":"sectiune","lvl":4,"label":"Secțiunea 1","name":"Primele de asigurare și limitele de răspundere","parent":"n4","arts":["12","13"]},{"id":"n6","kind":"sectiune","lvl":4,"label":"Secțiunea a 2-a","name":"Riscuri acoperite prin contractul de asigurare obligatorie de răspundere civilă auto","parent":"n4","arts":["14","15","16","17"]},{"id":"n7","kind":"sectiune","lvl":4,"label":"Secțiunea a 3-a","name":"Notificarea producerii cazului asigurat și constatarea pagubelor","parent":"n4","arts":["18","19","20","21","22","23"]},{"id":"n8","kind":"sectiune","lvl":4,"label":"Secțiunea a 4-a","name":"Stabilirea și plata despăgubirilor și indemnizațiilor de asigurare","parent":"n4","arts":["24","25","26","27","28","29","30","31"]},{"id":"n9","kind":"capitol","lvl":3,"label":"Capitolul III","name":"BIROUL NAȚIONAL AL ASIGURĂTORILOR DE AUTOVEHICULE","parent":null,"arts":[]},{"id":"n10","kind":"sectiune","lvl":4,"label":"Secțiunea 1","name":"Organizarea și funcționarea Biroului Național al Asigurătorilor de Autovehicule","parent":"n9","arts":["32","33","34","35","36","37"]},{"id":"n11","kind":"sectiune","lvl":4,"label":"Secțiunea a 2-a","name":"Competențele Biroului Național al Asigurătorilor de Autovehicule","parent":"n9","arts":["38","39","40","41"]},{"id":"n12","kind":"capitol","lvl":3,"label":"Capitolul IV","name":"VERIFICAREA ASIGURĂRII OBLIGATORII DE RĂSPUNDERE CIVILĂ AUTO","parent":null,"arts":["42","43"]},{"id":"n13","kind":"capitol","lvl":3,"label":"Capitolul V","name":"DISPOZIȚII TRANZITORII ȘI FINALE","parent":null,"arts":["44","45"]}],"articles":[{"id":"1","num":"1","title":"Obiectul de reglementare și domeniul de aplicare","node":"n2","blocks":[{"k":"al","n":"1","id":"a1","t":"Prezenta lege reglementează:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"raporturile juridice dintre asigurători, asigurați și persoane terțe ce derivă din contractul de asigurare obligatorie de răspundere civilă auto pentru pagube produse de accidente de vehicule, precum și modul de realizare a acestui tip de asigurare;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"modul de organizare și funcționare a Biroului Național al Asigurătorilor de Autovehicule.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Domeniul de aplicare a prezentei legi se referă la asigurarea obligatorie de răspundere civilă auto, respectiv, la obligația de a încheia contracte și de a stabili excepțiile de la această obligație, la limitele teritoriale de acoperire și la limitele de răspundere a asigurării, la drepturile și obligațiile asigurătorilor, asiguraților și persoanelor păgubite, la riscurile acoperite și excluderile, la procedura de stabilire și de plată a despăgubirilor de asigurare și de verificare a asigurării, la facilitățile și penalitățile aplicabile asigurătorilor și asiguraților, precum și la instituțiile responsabile pentru furnizarea sau prezentarea informațiilor necesare stabilirii pagubei.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În temeiul prezentei legi, asigurărilor obligatorii de răspundere civilă auto externă li se aplică și prevederile Regulamentului general al Consiliului Birourilor Sistemului Internațional de Asigurări „Carte Verde” sau alte reglementări aferente.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Prevederile prezentei legi nu se aplică vehiculelor care nu sunt supuse înmatriculării de stat și vehiculelor care sunt utilizate de serviciile Forțelor Armate din Republica Moldova.","lvl":1},{"k":"al","n":"5","id":"a5","t":"În textul prezentei legi, prin pagubă, despăgubiri de asigurare, persoane păgubite, contract de asigurare obligatorie de răspundere civilă auto, certificat de înmatriculare se va înțelege daună, vătămare corporală, deces și prejudiciu moral, respectiv, despăgubiri și indemnizații de asigurare, persoane păgubite (vătămate), contract de asigurare obligatorie de răspundere civilă auto internă și externă, certificat de înmatriculare sau de înregistrare, cu excepția cazului în care nu se prevede altfel.","lvl":1},{"k":"al","n":"6","id":"a6","t":"În limitele prevederilor prezentei legi, Banca Națională a Moldovei exercită atribuții de reglementare, supraveghere și control cu privire la:","lvl":1},{"k":"lit","n":"a","id":"a6.la","t":"acordarea, reperfectarea, suspendarea și retragerea licenței pentru asigurarea obligatorie RCA internă și/sau pentru asigurarea obligatorie RCA internă şi externă;","lvl":2},{"k":"lit","n":"b","id":"a6.lb","t":"primele de asigurare obligatorie RCA;","lvl":2},{"k":"lit","n":"c","id":"a6.lc","t":"Sistemul informaţional automatizat de stat în domeniul asigurărilor obligatorii RCA;","lvl":2},{"k":"lit","n":"d","id":"a6.ld","t":"Biroul Național al Asigurătorilor de Autovehicule.","lvl":2},{"k":"al","n":"7","id":"a7","t":"În limitele prevederilor prezentei legi, Comisia Națională a Pieței Financiare exercită atribuții de reglementare, supraveghere și control cu privire la:","lvl":1},{"k":"lit","n":"a","id":"a7.la","t":"contractul de asigurare obligatorie RCA, riscuri acoperite și clauze contractuale de excludere;","lvl":2},{"k":"lit","n":"b","id":"a7.lb","t":"constatarea amiabilă a accidentului;","lvl":2},{"k":"lit","n":"c","id":"a7.lc","t":"categoriile de persoane păgubite, drepturile și obligațiile acestora;","lvl":2},{"k":"lit","n":"d","id":"a7.ld","t":"exercitarea drepturilor și obligațiilor asigurătorului RCA;","lvl":2},{"k":"lit","n":"e","id":"a7.le","t":"procedura de notificare a producerii cazului asigurat şi constatarea pagubelor;","lvl":2},{"k":"lit","n":"f","id":"a7.lf","t":"stabilirea şi plata despăgubirilor şi indemnizațiilor de asigurare;","lvl":2},{"k":"lit","n":"g","id":"a7.lg","t":"decontarea directă dintre asigurătorii RCA;","lvl":2},{"k":"lit","n":"h","id":"a7.lh","t":"sistemele informaționale automatizate de evaluare în domeniul auto.","lvl":2},{"k":"al","n":"8","id":"a8","t":"Banca Națională a Moldovei asigură implementarea, funcționarea, dezvoltarea şi administrarea Sistemului informațional automatizat de stat în domeniul asigurărilor obligatorii RCA.","lvl":1}]},{"id":"2","num":"2","title":"Obiectul asigurării","node":"n2","blocks":[{"k":"al","n":"1","id":"a1","t":"Obiect al asigurării obligatorii de răspundere civilă auto îl constituie răspunderea civilă a proprietarului și/sau a utilizatorului de vehicul pentru orice pagubă produsă de un accident de vehicul în limitele teritoriale de acoperire și în limitele de răspundere ale acestei asigurări.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Teritoriul pe care vehiculul staționează în mod obișnuit se referă la:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"teritoriul statului în care vehiculul are o placă cu numărul de înmatriculare, fie că aceasta este permanentă sau temporară; sau","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"în cazul în care vehiculul nu deține placă cu număr de înmatriculare, dar are un contract de asigurare obligatorie de răspundere civilă auto sau un semn distinctiv similar acestei plăci, teritoriul statului în care a fost eliberat contractul de asigurare obligatorie de răspundere civilă auto sau semnul respectiv; sau","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"în cazul în care vehiculul nu deține placă cu număr de înmatriculare, contract de asigurare obligatorie de răspundere civilă auto și nici vreun semn distinctiv similar acestei plăci, teritoriul statului în care proprietarul vehiculului este rezident permanent; sau","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"în cazul în care vehiculul nu are placă cu număr de înmatriculare sau are o placă care nu corespunde sau nu mai corespunde cu vehiculul și a fost implicat într-un accident, teritoriul statului în care a avut loc accidentul, în ale cărui limite va fi soluționată cererea de despăgubire de către biroul național al asigurătorilor sau organismul de plată a despăgubirilor.","lvl":2}]},{"id":"3","num":"3","title":"Noțiuni principale","node":"n2","blocks":[{"k":"p","id":"x1","t":"În sensul prezentei legi, următoarele noțiuni semnifică:","lvl":1},{"k":"p","id":"x2","t":"accident de vehicul – eveniment neprevăzut în care a fost implicat cel puțin un vehicul în urma căruia au rezultat pagube;","lvl":1,"def":"accident de vehicul"},{"k":"p","id":"x3","t":"asigurare obligatorie de răspundere civilă auto pentru pagube produse de vehicule (în continuare – asigurare obligatorie RCA) – contract de asigurare, probat prin polița de asigurare obligatorie RCA (internă) și/sau certificat de asigurare „Carte Verde” (externă), prin care un asigurător licențiat să desfășoare activitate de asigurare obligatorie RCA se obligă, în baza unei prime de asigurare plătite de către asigurat, să despăgubească pagubele produse de un accident de vehicul care a avut loc în perioada de valabilitate a contractului de asigurare;","lvl":1},{"k":"p","id":"x4","t":"asigurător RCA (societate de asigurare) – asigurător licențiat să desfășoare activitate de asigurare obligatorie RCA;","lvl":1,"def":"asigurător RCA (societate de asigurare)"},{"k":"p","id":"x5","t":"asigurat – proprietar și/sau utilizator al unui vehicul a cărui răspundere civilă delictuală este preluată de către un asigurător RCA în baza contractului de asigurare obligatorie RCA;","lvl":1,"def":"asigurat"},{"k":"p","id":"x6","t":"birou național al asigurătorilor (în continuare – birou național) – organizație profesională care este constituită în conformitate cu Recomandarea nr. 5 din 25 ianuarie 1949, adoptată de către Subcomitetul pentru transport rutier al Comitetului pentru transport pe uscat din cadrul Comisiei Economice pentru Europa a Organizației Națiunilor Unite, și care grupează asigurătorii care sunt licențiați dintr-un stat să practice activitatea de asigurare obligatorie RCA;","lvl":1,"def":"birou național al asigurătorilor (în continuare"},{"k":"p","id":"x7","t":"Biroul Național al Asigurătorilor de Autovehicule (în continuare – BNAA) – birou național din Republica Moldova, asociație profesională, independentă și autonomă, a tuturor societăților de asigurare licențiate conform legislației să practice în Republica Moldova activitate de asigurare obligatorie RCA, care îndeplinește atribuțiile de birou național în Sistemul Internațional de Asigurări „Carte Verde”, de organism de plată a despăgubirilor de asigurare, precum și alte atribuții conferite de prezenta lege;","lvl":1},{"k":"p","id":"x8","t":"bonus-malus – sistem prin care asiguratul este încadrat în una dintre clasele de bonus (ceea ce conduce la reducerea primei de asigurare) sau în una dintre clasele de malus (ceea ce conduce la majorarea primei de asigurare) în funcție de istoricul asiguratului în perioada de referință;","lvl":1},{"k":"p","id":"x9","t":"certificat de asigurare „Carte Verde” – document internațional de asigurare, eliberat în numele unui birou național în conformitate cu oricare dintre modelele aprobate de către Consiliul Birourilor Sistemului Internațional de Asigurări „Carte Verde”, care atestă existența asigurării obligatorii RCA externe;","lvl":1,"def":"certificat de asigurare „Carte Verde”"},{"k":"p","id":"x10","t":"Consiliul Birourilor Sistemului Internațional de Asigurări „Carte Verde” (în continuare – Consiliul Birourilor) – asociație internațională non-profit a birourilor naționale din statele membre ale Sistemului Internațional de Asigurări „Carte Verde”, organizată în conformitate cu legislația din Belgia, care este responsabilă pentru administrarea și coordonarea relațiilor dintre birourile naționale privind asigurarea obligatorie RCA;","lvl":1},{"k":"p","id":"x11","t":"constatare amiabilă a accidentului – procedură simplificată și benevolă de documentare a accidentului de vehicul soldat doar cu daune materiale nesemnificative, realizată de către conducătorii de vehicule implicați în accident în mod electronic prin intermediul aplicației guvernamentale integrate a serviciilor electronice sau prin completarea și semnarea de către conducătorii de vehicule implicați în accident a formularului „Constatare amiabilă de accident”, stabilit de către Comisia Națională a Pieței Financiare;","lvl":1,"def":"constatare amiabilă a accidentului"},{"k":"note","t":"[Art.3 noțiunea modificată prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"p","id":"x12","t":"daună materială nesemnificativă – daună cauzată prin avarierea sau distrugerea de bunuri în urma unui accident de vehicul, a cărei sumă nu depășește cuantumul maxim de despăgubire de asigurare stabilit prin actele normative ale Comisiei Naționale a Pieței Financiare;","lvl":1,"def":"daună materială nesemnificativă"},{"k":"p","id":"x13","t":"daună parțială – avarierea vehiculului în măsura în care recondiționarea sau înlocuirea părților lui componente și a pieselor avariate este posibilă și valoarea pagubei real suportate nu depășește 75% din valoarea vehiculului la data producerii accidentului;","lvl":1,"def":"daună parțială"},{"k":"p","id":"x14","t":"daună totală – distrugere sau avariere a vehiculului în totalitate în măsura în care valoarea lucrărilor de recondiționare sau de înlocuire a părților lui componente și a pieselor avariate este egală sau depășește 75% din valoarea vehiculului la data producerii accidentului;","lvl":1,"def":"daună totală"},{"k":"p","id":"x15","t":"decontare directă – serviciu auxiliar de gestionare a pagubelor produse de accidente de vehicule de către asigurătorii RCA a propriilor asigurați, care se ofertează de către asigurătorul RCA, iar achiziția acestuia este opțională pentru asigurat;","lvl":1,"def":"decontare directă"},{"k":"p","id":"x16","t":"dosar de daune – dosar care include totalitatea documentelor necesare constatării daunelor și soluționării cererii de despăgubire;","lvl":1,"def":"dosar de daune"},{"k":"p","id":"x17","t":"limitele teritoriale de acoperire ale asigurării obligatorii RCA:","lvl":1},{"k":"lit","n":"a","id":"la","t":"teritoriul Republicii Moldova – asigurarea internă; sau","lvl":1,"def":"teritoriul Republicii Moldova"},{"k":"lit","n":"b","id":"lb","t":"teritoriile statelor membre ale Sistemului Internațional de Asigurări „Carte Verde”– asigurarea externă;","lvl":1},{"k":"p","id":"x18","t":"persoană păgubită (vătămată) – orice persoană îndreptățită să primească despăgubiri de asigurare pentru o pagubă rezultată în urma producerii unui risc acoperit printr-un contract de asigurare obligatorie RCA sau care, în condițiile prezentei legi, este îndreptățită de a formula către BNAA pretențiile de despăgubire;","lvl":1,"def":"persoană păgubită (vătămată)"},{"k":"p","id":"x19","t":"poliță de asigurare obligatorie RCA – document, cu valabilitate în limitele teritoriului Republicii Moldova, care probează încheierea contractului de asigurare obligatorie RCA internă și certifică existența acestei asigurări;","lvl":1,"def":"poliță de asigurare obligatorie RCA"},{"k":"p","id":"x20","t":"prejudiciu – efect negativ suferit de către persoana păgubită în urma producerii unui risc acoperit printr-un contract de asigurare obligatorie RCA;","lvl":1,"def":"prejudiciu"},{"k":"p","id":"x21","t":"primă de asigurare de bază – primă calculată prin metode actuariale, în baza informațiilor statistice ale asigurătorului RCA, care constă din prima de risc estimată și factorul de încărcare;","lvl":1,"def":"primă de asigurare de bază"},{"k":"p","id":"x22","t":"primă de referință – primă de asigurare indicativă, calculată de către Banca Națională a Moldovei sau de către o societate cu expertiză recunoscută în domeniu, contractată de către Banca Națională a Moldovei, în baza datelor statistice la nivelul pieței de asigurări obligatorii RCA interne și externe;","lvl":1,"def":"primă de referință"},{"k":"p","id":"x23","t":"Regulamentul General al Consiliului Birourilor – document oficial, adoptat de către Consiliul Birourilor la Rethymno (Creta) la 30 mai 2002, care încorporează toate prevederile obligatorii ce guvernează relațiile dintre birourile naționale din statele membre ale Sistemului Internațional de Asigurări „Carte Verde”;","lvl":1},{"k":"p","id":"x24","t":"unitate de reparații – persoană juridică înregistrată și autorizată în Republica Moldova să desfășoare activitate de bază de întreținere și reparație a vehiculelor, în conformitate cu legislația;","lvl":1,"def":"unitate de reparații"},{"k":"p","id":"x25","t":"utilizator – persoană fizică sau juridică care deține sau utilizează un vehicul, al cărui proprietar îi acordă dreptul de folosință asupra acestuia, pe o anumită perioadă, în baza unui contract de locațiune, a unui contract de leasing sau a altui act juridic întocmit în conformitate cu legislația, precum și altă persoană care conduc vehiculul cu sau fără consimțământul proprietarului. În cadrul cursurilor de șoferi, utilizator se consideră persoana care efectuează instruirea în conducerea vehiculului;","lvl":1,"def":"utilizator"},{"k":"p","id":"x26","t":"valoare rămasă – valoare a părților din vehicul rămase neavariate, demontabile și valorificabile, în caz de daună totală a acestuia;","lvl":1,"def":"valoare rămasă"},{"k":"p","id":"x27","t":"vehicul – sistem mecanic, cu sau fără autopropulsie, destinat transportului de persoane sau de bunuri ori echipat cu mecanisme care pot executa anumite lucrări, dar care nu se deplasează pe șine, inclusiv orice tip de remorcă, indiferent dacă este cuplată sau nu, pentru care în Republica Moldova există obligația legală de înmatriculare.","lvl":1,"def":"vehicul"}]},{"id":"4","num":"4","title":"Obligația de asigurare RCA","node":"n2","blocks":[{"k":"al","n":"1","id":"a1","t":"Persoanele care utilizează vehicule înregistrate în Republica Moldova sunt obligate să încheie contracte de asigurare obligatorii RCA pentru orice cazuri de răspundere civilă delictuală pentru pagube produse de accidente de vehicule. Contractul de asigurare obligatorie RCA acoperă în mod obligatoriu atât daunele materiale, cât și vătămările corporale, decesul și prejudiciile morale.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Prin contractul de asigurare obligatorie RCA externă este acoperită orice pagubă produsă de un accident de vehicul în limitele teritoriale de acoperire ale acestui contract, în conformitate cu legislația din statul unde a avut loc accidentul.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Persoanele fizice și juridice care dețin vehicule retro (de colecție, de interes istoric sau etnografic) și care utilizează vehicule exclusiv în scopul antrenamentelor, curselor, întrecerilor sau raliurilor organizate legal nu sunt obligate să încheie un contract de asigurare obligatorie RCA, însă, ținând cont de riscurile ce derivă din aceste activități, proprietarii acestor vehicule sau organizatorii competițiilor pot opta pentru asigurări facultative. În cazul în care cu aceste vehicule se circulă pe drumurile publice, încheierea unui contract de asigurare obligatorie RCA este indispensabilă.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Persoanele care intră pe teritoriul Republicii Moldova, conducând vehicule înregistrate în statele terțe, se consideră asigurate dacă:","lvl":1},{"k":"lit","n":"a","id":"a4.la","t":"sunt asigurate în conformitate cu prezenta lege;","lvl":2},{"k":"lit","n":"b","id":"a4.lb","t":"posedă documente de asigurare internațională, valabile pe teritoriul Republicii Moldova.","lvl":2}]},{"id":"5","num":"5","title":"Cazul asigurat","node":"n2","blocks":[{"k":"al","n":"1","id":"a1","t":"În cadrul asigurării obligatorii RCA, cazul asigurat este accidentul produs de un vehicul al cărui proprietar și/sau utilizator a îndeplinit obligația de asigurare obligatorie RCA, cu producerea de pagube:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"atât în timpul deplasării, cât și în timpul staționării vehiculului;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"în urma desprinderii accidentale, în timpul deplasării vehiculului, a remorcilor, semiremorcilor sau atașelor;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"de dispozitivele sau instalațiile cu care a fost echipat vehiculul;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"ca urmare a scurgerii, risipirii sau căderii accidentale a substanțelor, a materialelor sau a obiectelor transportate;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"la urcarea în vehicul și la coborârea din acesta.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Nu se consideră caz asigurat dacă accidentul a avut loc ca urmare a imposibilității fortuite de executare, inclusiv prin diferite măsuri militare instituite pe durata stării de urgență, de asediu sau de război sau prin acțiuni provocate de calamități naturale, explozii nucleare, radiație sau poluare radioactivă, dezordini în masă, precum și de activități teroriste.","lvl":1}]},{"id":"6","num":"6","title":"Exigențele față de asigurătorul RCA","node":"n2","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurătorul poate desfășura activitate de asigurare obligatorie RCA internă dacă îndeplinește cumulativ, suplimentar la cerințele stabilite prin legislația privind activitatea de asigurare sau de reasigurare, următoarele condiții:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"dispune cel puțin de câte un reprezentant de despăgubiri conform prevederilor prezentei legi;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"dispune de tehnică de calcul și sisteme informatice adecvate și de personal care să permită ținerea evidenței detaliate a documentelor de asigurare și centralizarea informațiilor/datelor colectate și are capacitatea de a comunica electronic aceste informații către Sistemul informațional automatizat de stat în domeniul asigurărilor obligatorii RCA, constituit de către Banca Națională a Moldovei. În acest sens, este obligatoriu ca sistemul informațional al asigurătorului să permită transmiterea și comunicarea în regim online, prin tehnologiile web, a informațiilor despre asigurarea obligatorie RCA între sediul central și/sau sucursalele/subdiviziunile asigurătorului RCA și Banca Națională a Moldovei;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"nu se află în procedură de rezoluție financiară sau de insolvabilitate în conformitate cu legislația privind activitatea de asigurare sau de reasigurare și cu cea a insolvabilității;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"dispune cel puțin de unul dintre sistemele informaționale automatizate de evaluare în domeniul auto, care include prețuri din cataloagele producătorilor de piese de schimb, de părți componente și de materiale necesare reparației și care corespunde cerințelor stabilite în actele normative ale Comisiei Naționale a Pieței Financiare.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Asigurătorul poate desfășura activitate de asigurare obligatorie RCA externă dacă îndeplinește cumulativ, suplimentar la condițiile stabilite la alin. (1), următoarele cerințe:","lvl":1,"r":[[145,154,{"al":"1","art":"6"}]]},{"k":"lit","n":"a","id":"a2.la","t":"dispune de experiență de cel puțin 2 ani în domeniul asigurării obligatorii RCA (acumulată pe teritoriul Republicii Moldova sau pe teritoriul unui stat terț, în cazul în care se solicită înființarea sucursalei);","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"participă cu mijloace financiare proprii în Fondul de compensare, constituit conform prevederilor prezentei legi, în cuantumul stabilit în actele normative ale Băncii Naționale a Moldovei;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"participă cu mijloace financiare proprii la formarea garanției financiare externe, stabilită de către Consiliul Birourilor și prevăzută de prezenta lege, pentru perioada în care este în vigoare recomandarea acestuia de menținere a unei astfel de garanții;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"dispune de rata solvabilității de cel puțin 120%, confirmată de actuar, la momentul depunerii cererii/documentelor pentru obținerea dreptului de a desfășura activitate de asigurare obligatorie RCA externă.","lvl":2}]},{"id":"7","num":"7","title":"Reprezentantul de despăgubiri","node":"n2","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurătorul RCA este obligat să numească în cel puțin 3 municipii din Republica Moldova (Chișinău, Bălți, Comrat) câte un reprezentant de despăgubiri, responsabil să reprezinte asigurătorul RCA în limitele împuternicirilor atribuite.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Reprezentantul de despăgubiri este mandatat să reprezinte asigurătorul RCA în scopul instrumentării cazurilor de daună în limitele împuternicirilor atribuite. În acest scop, reprezentantul de despăgubiri întocmește dosarul de daună și întreprinde toate măsurile necesare pentru soluționarea cererilor de despăgubire depuse de către persoana păgubită pentru pagubele produse de un accident de vehicul al cărui proprietar și/sau utilizator a îndeplinit obligația de asigurare obligatorie RCA.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Reprezentantul de despăgubiri poate acționa în numele mai multor asigurători RCA.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Reprezentantul de despăgubiri trebuie să fie mandatat cu dreptul de a recepționa cereri, de a colecta documentele necesare instrumentării dosarului de daune, de a întocmi și a semna procesul-verbal de constatare a daunelor.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Numirea unui reprezentant de despăgubiri nu exclude dreptul persoanei păgubite de a acționa direct împotriva persoanei culpabile care a cauzat paguba sau împotriva asigurătorului RCA al acesteia, după caz.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Asigurătorul RCA este obligat să informeze Banca Națională a Moldovei cu privire la numele și prenumele, IDNP-ul reprezentantului de despăgubiri, adresa sucursalei/subdiviziunii asigurătorului RCA în care acesta își va desfășura activitatea, în cazul în care reprezentantul de despăgubiri este o persoană fizică, sau cu privire la denumirea, adresa sediului, IDNO-ul, în cazul în care reprezentantul de despăgubiri este o persoană juridică, precum și cu privire la toate modificările datelor ce țin de aceștia, în termen de 7 zile lucrătoare de la numire ori modificare.","lvl":1}]},{"id":"8","num":"8","title":"Încheierea contractului de asigurare obligatorie RCA","node":"n3","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurarea obligatorie RCA se realizează nemijlocit prin încheierea unui contract de asigurare între proprietarul și/sau utilizatorul vehiculului și asigurătorul RCA, care se întocmește pe suport de hârtie și/sau prin mijloace electronice, în conformitate cu actele normative ale Comisiei Naționale a Pieței Financiare. În cazul în care contractul de asigurare obligatorie RCA este încheiat prin utilizarea oricărui mijloc electronic, iar persoana nu l-a semnat electronic, se prezumă că prin plata primei de asigurare asiguratul și-a exprimat consimțământul privind încheierea contractului.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Contractul de asigurare obligatorie RCA se încheie între asigurător și asigurat, fără indicarea persoanelor admise să utilizeze vehiculul (număr nelimitat de utilizatori). În temeiul contractului de asigurare obligatorie RCA, riscul oricărui utilizator de vehicul este acoperit indiferent dacă acesta este încheiat de persoane fizice sau juridice ori din numele acestora, cu excepțiile prevăzute de prezenta lege.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Dacă persoana fizică asigurată, cu excepția întreprinzătorilor individuali sau a persoanelor care, în sensul Codului fiscal, prestează servicii profesionale și desfășoară activități profesionale independente, transmite în posesie unei persoane juridice vehiculul pentru care a fost încheiat contractul de asigurare obligatorie RCA, în baza unui contract de locațiune sau a altui act juridic întocmit în condițiile legislației, riscul celor admiși de către persoana juridică să utilizeze vehiculul este considerat asigurat în temeiul contractului încheiat. Prin derogare de la prevederile prezentului alineat, asigurătorul are dreptul de a înainta acțiune de regres conform art. 30.","lvl":1,"r":[[109,123,{"a":"cod:fiscal","whole":true}],[673,680,{"art":"30"}]]},{"k":"al","n":"4","id":"a4","t":"Dacă persoana juridică asigurată transmite în posesie unei întreprinderi care desfășoară activitate de închiriere a vehiculelor ori activitate de transport rutier de persoane sau bunuri în regim de taxi vehiculul pentru care a fost încheiat contractul de asigurare obligatorie RCA, în baza unui contract de locațiune sau a altui act juridic întocmit în condițiile legislației, riscul celor admiși de către întreprindere să utilizeze vehiculul este considerat asigurat în temeiul contractului încheiat. Prin derogare de la prevederile prezentului alineat, asigurătorul are dreptul de a înainta acțiune de regres conform art. 30.","lvl":1,"r":[[619,626,{"art":"30"}]]},{"k":"al","n":"5","id":"a5","t":"Cererea pentru încheierea contractului de asigurare obligatorie RCA se depune la asigurătorul RCA. Asigurătorul nu are dreptul să refuze examinarea și soluționarea cererii de asigurare.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Încheierea contractului de asigurare obligatorie RCA internă se probează cu polița de asigurare RCA, iar încheierea contractului de asigurare obligatorie RCA externă – cu certificatul de asigurare „Carte Verde”. Polița de asigurare obligatorie RCA și/sau certificatul de asigurare „Carte Verde” se eliberează cu condiția achitării integrale a primei de asigurare. În cazul autorităților contractante care participă în condițiile Legii nr. 131/2015 privind achizițiile publice la procedura de achiziție publică, polița de asigurare obligatorie RCA și/sau certificatul de asigurare „Carte Verde” pot fi eliberate anterior achitării de către acestea a primei de asigurare.","lvl":1,"r":[[429,447,{"a":"lege:131/2015","whole":true}]]},{"k":"note","t":"[Art.8 al.(6) modificat prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"al","n":"7","id":"a7","t":"În cazul înstrăinării vehiculului, asiguratul este obligat să informeze asigurătorul RCA. În cazul înstrăinării vehiculului, cu informarea asigurătorului RCA, asiguratul are opțiunea de a cesiona drepturile din contractul de asigurare obligatorie RCA noului proprietar sau de a rezoluționa contractul existent. Rezoluțiunea poate avea loc în cazul în care nu s-au plătit sau nu se datorează despăgubiri de asigurare pentru pagubele produse în perioada de valabilitate a contractului de asigurare obligatorie RCA. În cazul cesiunii, asigurătorul RCA va ajusta prima de asigurare în baza factorului de risc respectiv al noului proprietar.","lvl":1},{"k":"al","n":"8","id":"a8","t":"Dacă în perioada de valabilitate a contractului de asigurare obligatorie RCA are loc înstrăinarea vehiculului fără informarea asigurătorului RCA, iar contractul rămâne în vigoare și se produce cazul asigurat, asigurătorul RCA poartă răspundere cu dreptul de ajustare și de încasare, după caz, a unei prime de asigurare suplimentare de la noul proprietar, cu cesiunea drepturilor din contractul de asigurare obligatorie RCA.","lvl":1},{"k":"al","n":"9","id":"a9","t":"Orice modificări în contractul de asigurare obligatorie RCA produc efecte din momentul operării acestora în Sistemul informațional automatizat de stat în domeniul asigurărilor obligatorii RCA, administrat de către Banca Națională a Moldovei.","lvl":1},{"k":"al","n":"10","id":"a10","t":"Duplicatul poliței de asigurare RCA și/sau al certificatului de asigurare „Carte Verde” se eliberează la cererea asiguratului după anularea documentelor pierdute, furate sau deteriorate. Costul duplicatului este acoperit de către solicitant.","lvl":1},{"k":"al","n":"11","id":"a11","t":"Forma și conținutul cererilor de asigurare, ale contractelor de asigurare obligatorie RCA, ale formularului „Constatare amiabilă de accident”, precum și forma și conținutul poliței de asigurare RCA și ale certificatului de asigurare „Carte Verde” sunt unice pentru toți asigurătorii și se stabilesc conform actului normativ al Comisiei Naționale a Pieței Financiare. Forma și conținutul certificatului de asigurare „Carte Verde” se stabilesc în conformitate cu modelul și condițiile aprobate de către Consiliul Birourilor.","lvl":1},{"k":"al","n":"12","id":"a12","t":"Persoana care are în proprietate și/sau în utilizare mai mult de un vehicul înmatriculat ori supus înmatriculării în Republica Moldova poate încheia un singur contract de asigurare obligatorie RCA, în care va indica numărul vehiculelor, caracteristicile lor tehnice și datele de identificare, situație în care asigurătorul va elibera polița de asigurare RCA și/sau certificatul de asigurare „Carte Verde” pentru fiecare vehicul.","lvl":1},{"k":"al","n":"13","id":"a13","t":"La încheierea contractului de asigurare obligatorie RCA, proprietarul și/sau utilizatorul vehiculului va permite asigurătorului RCA să verifice starea tehnică a vehiculului și să solicite istoricul daunelor.","lvl":1},{"k":"al","n":"14","id":"a14","t":"Emiterea contractelor de asigurare obligatorie RCA se efectuează în sucursalele/subdiviziunile asigurătorilor RCA sau în subdiviziunile intermediarilor în asigurări, dotate cu echipament de casă și control și tehnică de calcul, platforme web care să permită înregistrarea contractelor, ținerea evidenței și transmiterea informației către Sistemul informațional automatizat de stat în domeniul asigurărilor obligatorii RCA al asigurătorului, al BNAA-ului și al Băncii Naționale a Moldovei.","lvl":1},{"k":"al","n":"15","id":"a15","t":"Din momentul depunerii cererii și al încheierea contractului de asigurare obligatorie RCA și pe parcursul valabilității acestuia, asiguratul permite accesul asigurătorului RCA la datele din Sistemul informațional automatizat de stat în domeniul asigurărilor obligatorii RCA, la înregistrările privind accidentele și daunele anterioare și oferă toată informația solicitată de către asigurătorul RCA pentru evaluarea riscului și calcularea primei de asigurare.","lvl":1}]},{"id":"9","num":"9","title":"Contractul de asigurare obligatorie RCA. Limitele teritoriale","node":"n3","blocks":[{"k":"al","n":"1","id":"a1","t":"Contractul de asigurare obligatorie RCA se încheie pe un termen de 12 luni, cu excepția cazurilor prevăzute la alin. (2), (2¹) și (3).","lvl":1,"r":[[111,120,{"al":"2","art":"9"}],[122,126,{"al":"2_1","art":"9"}],[130,133,{"al":"3","art":"9"}]]},{"k":"al","n":"2","id":"a2","t":"Contractul de asigurare obligatorie RCA externă poate fi încheiat pentru perioade de asigurare mai mici de 12 luni, dar nu mai mici de 15 zile.","lvl":1},{"k":"al","n":"2¹","id":"a2_1","t":"În cazul autovehiculelor înmatriculate provizoriu pentru probe se permite încheierea contractelor de asigurare pe perioade de asigurare mai mici de 12 luni, dar nu mai mici de 30 de zile.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Persoana care folosește un vehicul înmatriculat în străinătate, dar neasigurat pe teritoriul Republicii Moldova sau a cărui perioadă de asigurare expiră în timpul aflării acesteia pe teritoriul Republicii Moldova este obligată să încheie contract de asigurare obligatorie RCA internă cu asigurătorul RCA la intrarea vehiculului pe teritoriul Republicii Moldova, la punctul de trecere a frontierei de stat sau cel târziu în ultima zi de valabilitate a documentului de asigurare. Contractul de asigurare se încheie pe toată perioada aflării pe teritoriul Republicii Moldova, dar pe un termen nu mai mic de 30 de zile.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Răspunderea asigurătorului începe:","lvl":1},{"k":"lit","n":"a","id":"a4.la","t":"în cazul contractelor de asigurare obligatorie RCA internă:","lvl":2},{"k":"dash","id":"d1","t":"din ziua următoare celei în care expiră valabilitatea contractului anterior de asigurare obligatorie RCA, pentru asiguratul care își îndeplinește obligația încheierii asigurării cel târziu în ultima zi de valabilitate a acestuia;","lvl":3},{"k":"dash","id":"d2","t":"din ziua următoare celei în care s-a încheiat contractul de asigurare obligatorie RCA, pentru persoanele care nu aveau o asigurare obligatorie RCA valabilă la momentul încheierii noii asigurări;","lvl":3},{"k":"dash","id":"d3","t":"din momentul indicat în contractul de asigurare obligatorie RCA, dar nu mai devreme de data intrării în vigoare a certificatului de înmatriculare provizoriu sau a certificatului de înmatriculare a vehiculului, pentru vehiculele comercializate care urmează să fie înmatriculate;","lvl":3},{"k":"dash","id":"d4","t":"din momentul indicat în contractul de asigurare obligatorie RCA, pentru persoanele care folosesc pe teritoriul Republicii Moldova un vehicul înmatriculat în străinătate;","lvl":3},{"k":"lit","n":"b","id":"a4.lb","t":"în cazul contractelor de asigurare obligatorie RCA externă – din data indicată în contract.","lvl":2},{"k":"al","n":"5","id":"a5","t":"Răspunderea asigurătorului încetează la ora 24:00 a ultimei zile de valabilitate a contractului de asigurare obligatorie RCA sau anterior acelei zile, în momentul radierii din circulație a vehiculului de către autoritățile competente.","lvl":1}]},{"id":"10","num":"10","title":"Suspendarea, rezoluțiunea și încetarea contractului de asigurare obligatorie RCA","node":"n3","blocks":[{"k":"al","n":"1","id":"a1","t":"Contractul de asigurare obligatorie RCA internă poate fi suspendat din momentul depunerii cererii persoanei care a încheiat contractul în următoarele circumstanțe:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"pe perioada suspendării dreptului de utilizare a vehiculului în conformitate cu legislația;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"pe perioada în care asiguratul a depus sau i-au fost retrase plăcile cu numerele de înmatriculare în conformitate cu legislația.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Asiguratul are obligația să imobilizeze vehiculul prin starea de nemișcare pe toată perioada suspendării contractului de asigurare obligatorie RCA.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Reluarea contractului de asigurare obligatorie RCA suspendat se efectuează din momentul depunerii cererii de către asigurat, cu prezentarea documentelor confirmative, care exclud circumstanțele menționate la alin. (1). Asigurătorul RCA nu datorează despăgubirea de asigurare dacă cazul asigurat s-a produs pe perioada suspendării contractului de asigurare obligatorie RCA.","lvl":1,"r":[[208,217,{"al":"1","art":"10"}]]},{"k":"al","n":"4","id":"a4","t":"Contractul de asigurare obligatorie RCA poate fi rezoluționat prin notificare, adresată în prealabil asigurătorului RCA, având la bază următoarele temeiuri:","lvl":1},{"k":"lit","n":"a","id":"a4.la","t":"retragerea licenței acestuia;","lvl":2},{"k":"lit","n":"b","id":"a4.lb","t":"notificarea de către asigurat, cu referire la transmiterea dreptului de proprietate asupra vehiculului, însoțită de documente justificative;","lvl":2},{"k":"lit","n":"c","id":"a4.lc","t":"acordul părților;","lvl":2},{"k":"lit","n":"d","id":"a4.ld","t":"alte cazuri prevăzute de prezenta lege.","lvl":2},{"k":"al","n":"5","id":"a5","t":"Prin derogare de la alin. (4), contractele de asigurare obligatorie RCA externă cu perioada de valabilitate de o lună sau mai mică pot fi rezoluționate fără aplicarea notificării, dar nu mai târziu de data începerii perioadei de asigurare.","lvl":1,"r":[[20,29,{"al":"4","art":"10"}]]},{"k":"al","n":"6","id":"a6","t":"Contractul de asigurare obligatorie RCA încetează de drept în următoarele circumstanțe:","lvl":1},{"k":"lit","n":"a","id":"a6.la","t":"în cazul radierii vehiculului din registrul de stat după notificarea asigurătorului;","lvl":2},{"k":"lit","n":"b","id":"a6.lb","t":"la data expirării perioadei stabilite în contract;","lvl":2},{"k":"lit","n":"c","id":"a6.lc","t":"în cazul emiterii unei hotărâri judecătorești definitive privind încetarea contractului;","lvl":2},{"k":"lit","n":"d","id":"a6.ld","t":"în alte cazuri prevăzute de legislație.","lvl":2},{"k":"al","n":"7","id":"a7","t":"La rezoluțiunea sau încetarea contractului de asigurare obligatorie RCA, asigurătorul restituie asiguratului prima de asigurare pentru zilele de până la expirarea perioadei de valabilitate a contractului, calculată din data rezoluțiunii sau încetării acestuia, dacă nu s-a plătit și nu se datorează nicio despăgubire de asigurare pentru orice pagubă produsă în perioada de valabilitate. Asigurătorul RCA are dreptul de a reține din valoarea primei de asigurare calculate pentru zilele de până la expirarea perioadei de valabilitate a contractului suma costurilor sale de până la 25% din prima de asigurare calculată pentru rambursare.","lvl":1},{"k":"al","n":"8","id":"a8","t":"Valabilitatea contractului de asigurare obligatorie RCA nu încetează în cazul producerii cazului asigurat și a plății despăgubirii de asigurare.","lvl":1},{"k":"al","n":"9","id":"a9","t":"Asigurătorul RCA și/sau intermediarul în asigurări poate informa, la solicitare, asigurații cu privire la încetarea contractului de asigurare obligatorie RCA și posibilitatea reîncheierii acestuia în termen de 30 de zile înainte de încetare sau în termen de 5 zile de la survenirea circumstanțelor de încetare a contractului.","lvl":1}]},{"id":"11","num":"11","title":"Asigurarea obligatorie RCA multiplă","node":"n3","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazul în care pentru același vehicul, la data producerii accidentului, sunt în vigoare mai multe contracte de asigurare obligatorie RCA, despăgubirea de asigurare se plătește în părți egale de către toți asigurătorii RCA.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Despăgubirea de asigurare se plătește integral de către asigurătorul RCA la care persoana păgubită a depus cererea, urmând ca, ulterior, asigurătorul RCA în cauză să inițieze procedurile de rigoare în adresa celorlalți asigurători RCA pentru recuperarea părții de despăgubire, plătită în numele acestora. Acțiunile de instrumentare a dosarului de daune al asigurătorului RCA care a plătit despăgubirea de asigurare sunt opozabile celorlalți asigurători în limitele prevederilor prezentei legi.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Asiguratul are obligația de a informa asigurătorul RCA despre existența altor contracte de asigurare obligatorie RCA în vigoare pentru vehiculul implicat în accident.","lvl":1}]},{"id":"12","num":"12","title":"Primele de asigurare. Sistemul bonus-malus","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurătorul calculează prima de asigurare astfel încât să se acopere toate obligațiile ce decurg din contractul de asigurare obligatorie RCA.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Prima de asigurare care urmează a fi încasată de la asigurat se calculează prin aplicarea la prima de asigurare de bază a criteriilor de risc, a coeficienților de rectificare și a coeficientului bonus-malus. Prima de asigurare se plătește integral.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Asigurătorul RCA și intermediarul în asigurări sunt obligați să ofere asiguraților informații despre cuantumul primei de asigurare de bază, al coeficienților de rectificare și al coeficientului bonus-malus, care va fi aplicat asiguratului.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Primele de asigurare de bază și coeficienții de rectificare aferenți asigurării obligatorii RCA interne și externe se stabilesc de către asigurătorii RCA în baza calculelor actuariale interne ale acestora, potrivit cadrului metodologic de calculare și aplicare stabilit de către Banca Națională a Moldovei.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Primele de asigurare de bază și coeficienții de rectificare aferenți asigurării obligatorii RCA interne și externe, legalizați de către actuarul asigurătorului RCA, se prezintă de către asigurător spre examinare Băncii Naționale a Moldovei, până la punerea în aplicare, pentru a se asigura că acestea sunt suficiente pentru a acoperi cel puțin costurile de soluționare a cererilor de despăgubire și cheltuielile administrative ale asigurătorului RCA, conform actelor normative ale Băncii Naționale a Moldovei.","lvl":1},{"k":"al","n":"6","id":"a6","t":"În cazul în care informațiile furnizate de către asigurat, conform art. 8, nu corespund realității în momentul încheierii contractului de asigurare obligatorie RCA, prima de asigurare poate fi recalculată și modificată de către asigurătorul RCA după notificarea prealabilă a asiguratului.","lvl":1,"r":[[67,73,{"art":"8"}]]},{"k":"al","n":"7","id":"a7","t":"În cazul încălcării obligației de informare prevăzute la art.8 la data încheierii contractului de asigurare obligatorie RCA, pe parcursul perioadei de valabilitate a acestuia sau în cazul agravării riscului, asigurătorul RCA poate rezolvi contractul în termen de 20 de zile de la notificarea prealabilă a asiguratului dacă acesta din urmă nu dă acordul pentru modificarea condițiilor contractuale în condițiile alin. (6) al prezentului articol. În cazul producerii cazului asigurat în perioada de notificare, asigurătorul RCA poartă răspundere cu drept de încasare, după caz, a unei prime de asigurare suplimentare.","lvl":1,"r":[[57,62,{"art":"8"}],[411,420,{"al":"6","art":"12"}]]},{"k":"al","n":"8","id":"a8","t":"Asigurătorilor RCA și intermediarilor în asigurări li se interzice acordarea asiguratului a oricăror avantaje colaterale la încheierea unui contract de asigurare obligatorie RCA internă și externă (sub formă de cadouri, bonusuri, promoții, certificate, premii etc.), inclusiv din contul cheltuielilor de achiziții și/sau al marjei de profit.","lvl":1},{"k":"al","n":"9","id":"a9","t":"La determinarea cuantumului primei de asigurare de bază, asigurătorul RCA va lua în considerare istoricul despăgubirilor de asigurare plătite în cel puțin ultimii 5 ani pentru pagubele produse de accidente, cu implicarea conducătorului de vehicul care solicită asigurarea obligatorie RCA.","lvl":1},{"k":"al","n":"10","id":"a10","t":"Asigurătorul RCA furnizează Băncii Naționale a Moldovei, la cererea acesteia, următoarele informații:","lvl":1},{"k":"lit","n":"a","id":"a10.la","t":"modul de determinare a primei de asigurare;","lvl":2},{"k":"lit","n":"b","id":"a10.lb","t":"datele statistice în baza cărora este stabilită prima de asigurare;","lvl":2},{"k":"lit","n":"c","id":"a10.lc","t":"raportul actuarial privind calculul și modul de determinare a primei de asigurare;","lvl":2},{"k":"lit","n":"d","id":"a10.ld","t":"orice alte informații privind metoda de calcul al primei de asigurare.","lvl":2},{"k":"al","n":"11","id":"a11","t":"Banca Națională a Moldovei sau o societate cu expertiză recunoscută în domeniu, contractată de Banca Națională a Moldovei, calculează cel puțin o dată pe an primele de referință în baza datelor statistice (cumulate per piață), conform actelor normative ale Băncii Naționale a Moldovei. Banca Națională a Moldovei publică primele de referință, primele de bază și coeficienții de rectificare conform actelor sale normative.","lvl":1},{"k":"al","n":"12","id":"a12","t":"Banca Națională a Moldovei va respinge calculul actuarial al primei de asigurare de bază și al coeficienților de rectificare dacă primele de asigurare sunt mai mici decât primele de referință.","lvl":1},{"k":"al","n":"13","id":"a13","t":"Asigurătorii RCA care nu dispun de informație statistică suficientă, necesară calculului actuarial prevăzut de prezenta lege, aplică prima de referință potrivit deciziei Băncii Națională a Moldovei.","lvl":1},{"k":"al","n":"14","id":"a14","t":"Criteriile de aplicare pentru sistemul bonus-malus sunt prevăzute în actele normative ale Băncii Națională a Moldovei.","lvl":1},{"k":"al","n":"15","id":"a15","t":"Asigurătorul RCA sau Banca Națională a Moldovei eliberează solicitantului, în termen de până la 15 zile de la înregistrarea cererii acestuia, un certificat privind pagubele înregistrate pe parcursul ultimilor 5 ani de relații contractuale sau absența acestor pagube.","lvl":1}]},{"id":"13","num":"13","title":"Limitele de răspundere","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Limitele de răspundere ale asigurării obligatorii RCA interne sunt următoarele:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"pentru daune materiale produse de unul și același accident, indiferent de numărul persoanelor păgubite, limita de despăgubire este de 100000 de euro, cu echivalentul în lei la cursul oficial de schimb al leului moldovenesc, comunicat de către Banca Națională a Moldovei la data producerii accidentului;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"pentru vătămări corporale și decese cauzate de unul și același accident, limita de despăgubire este de 100000 de euro – pentru o persoană vătămată sau de 500000 de euro – pentru mai multe persoane vătămate, indiferent de numărul lor, cu echivalentul în lei la cursul oficial de schimb al leului moldovenesc, comunicat de către Banca Națională a Moldovei la data producerii accidentului;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"pentru daune materiale revendicate în baza procedurii de constatare amiabilă a accidentului de vehicul, cuantumul maxim de despăgubire este stabilit prin actele normative ale Comisiei Naționale a Pieței Financiare;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"pentru prejudiciile morale ca urmare a dizabilității sau a decesului persoanei vătămate cauzate de unul și același accident, limita de despăgubire este de 5000 de euro – pentru o persoană vătămată sau de 10000 de euro – pentru mai multe persoane vătămate, indiferent de numărul lor, cu echivalentul în lei la cursul oficial de schimb al leului moldovenesc, comunicat de către Banca Națională a Moldovei la data producerii accidentului.","lvl":2},{"k":"al","n":"2","id":"a2","t":"În cazul prejudiciilor morale prevăzute la alin. (1) lit. d), acestea, proporțional limitei de răspundere, vor fi compensate după cum urmează:","lvl":1,"r":[[43,60,{"al":"1","lit":"d","art":"13"}]]},{"k":"lit","n":"a","id":"a2.la","t":"în caz de deces al persoanei vătămate – 100%;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"în caz de încadrare în grad de dizabilitate severă – 90%, accentuată – 60%, medie – 30%.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Despăgubirile de asigurare prevăzute de contractul de asigurare obligatorie RCA se plătesc indiferent de numărul cazurilor de accidente care au avut loc în perioada de valabilitate a acestuia.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Dacă întinderea pagubelor produse de unul și același accident mai multor persoane, inclusiv cheltuielile suportate de acestea în procesul civil, depășește limita stabilită, despăgubirile de asigurare se acordă în acea limită stabilită pentru fiecare persoană păgubită, proporțional raportului dintre limita răspunderii și totalul pagubelor.","lvl":1},{"k":"al","n":"5","id":"a5","t":"În cazul în care întinderea pagubelor depășește limitele de răspundere stabilite la alin. (1), persoana păgubită are dreptul, în conformitate cu Codul civil, să intenteze persoanei culpabile de producerea accidentului o acțiune de recuperare a sumei care depășește aceste limite.","lvl":1,"r":[[84,93,{"al":"1","art":"13"}],[145,156,{"a":"cod:civil","whole":true}]]},{"k":"al","n":"6","id":"a6","t":"Proprietarul și/sau utilizatorul vehiculului are dreptul să încheie contract de asigurare benevolă (facultativă) de răspundere civilă pentru acoperirea pagubelor ce depășesc limitele de răspundere stabilite la alin. (1).","lvl":1,"r":[[210,219,{"al":"1","art":"13"}]]}]},{"id":"14","num":"14","title":"Riscuri acoperite de către asigurătorul RCA","node":"n6","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurătorul RCA are obligația de a plăti despăgubiri de asigurare persoanei păgubite pentru pagubele produse de un accident de vehiculul al cărui proprietar și/sau utilizator a îndeplinit obligația de asigurare obligatorie RCA.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Fără a se depăși limitele de răspundere prevăzute în contractul de asigurare obligatorie RCA, conform art. 13 alin. (1) și (2) și în condițiile în care cazul asigurat s-a produs în perioada de valabilitate a contractului, asigurătorul RCA acordă despăgubiri de asigurare pentru:","lvl":1,"r":[[102,119,{"art":"13","al":"1"}],[123,126,{"art":"13","al":"2"}]]},{"k":"lit","n":"a","id":"a2.la","t":"vătămări corporale sau deces, inclusiv pentru prejudicii morale;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"daune materiale, inclusiv costuri de radiere a vehiculului și cheltuieli de diminuare a daunei;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"costuri privind reparația vehiculului, dovedite prin documente emise de către unitățile de reparații sau prin documente emise în condițiile prezentei legi;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"cheltuieli de judecată suportate de persoana păgubită în procesul civil sau cheltuieli aferente în cazul soluționării alternative a litigiului, dacă soluția este favorabilă pentru persoana păgubită;","lvl":2},{"k":"lit","n":"e","id":"a2.le","t":"costul aferent unei singure evacuări a vehiculului avariat, care aparține persoanei păgubite, de la locul accidentului la locația reprezentantului de despăgubiri sau la unitatea de reparații aleasă de către persoana păgubită, în vederea reparării vehiculului, sau la cea mai apropiată locație de locul producerii accidentului sau la domiciliul persoanei păgubite, după caz, dacă respectivul vehicul nu se mai poate deplasa prin mijloace proprii sau deplasarea acestuia poate provoca pericol pentru siguranța traficului rutier.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Indiferent de locul în care s-a produs accidentul de vehicul, pe drumuri publice, pe drumuri care nu sunt deschise circulației publice, în încăperi și în orice alte locuri, atât în timpul deplasării, cât și în timpul staționării vehiculului al cărui proprietar și/sau utilizator a îndeplinit obligația de asigurare obligatorie RCA, asigurătorul RCA acordă despăgubiri de asigurare în limita de răspundere prevăzută în prezenta lege pentru:","lvl":1},{"k":"lit","n":"a","id":"a3.la","t":"paguba produsă de orice dispozitiv sau instalație cu care a fost echipat vehiculul, inclusiv paguba produsă din cauza desprinderii accidentale a remorcii, a semiremorcii ori a atașului tractat de vehicul;","lvl":2},{"k":"lit","n":"b","id":"a3.lb","t":"paguba produsă din culpa conducătorului de vehicul al cărui proprietar și/sau utilizator a îndeplinit obligația de asigurare obligatorie RCA;","lvl":2},{"k":"lit","n":"c","id":"a3.lc","t":"paguba provocată persoanelor păgubite de caracteristicile, acțiunea ori inacțiunea vehiculului, de alt lucru antrenat în deplasarea vehiculului sau de scurgerea, risipirea ori căderea accidentală a substanțelor, a materialelor sau a obiectelor transportate;","lvl":2},{"k":"lit","n":"d","id":"a3.ld","t":"pagubele provocate persoanelor păgubite de deschiderea ușilor vehiculului de către pasagerii acestuia în timpul deplasării sau atunci când vehiculul este oprit sau staționează;","lvl":2},{"k":"lit","n":"e","id":"a3.le","t":"pagubele produse persoanelor păgubite drept consecință a conducerii vehiculului de către o persoană în stare de ebrietate survenită în urma consumului de alcool, droguri și/sau alte substanțe cu efecte similare.","lvl":2},{"k":"al","n":"4","id":"a4","t":"Pagubele produse de o remorcă sau semiremorcă se acoperă de asigurarea obligatorie RCA a proprietarului sau a utilizatorului vehiculului-tractor doar dacă remorca sau semiremorca:","lvl":1},{"k":"lit","n":"a","id":"a4.la","t":"este tractată de vehiculul-tractor respectiv; ori","lvl":2},{"k":"lit","n":"b","id":"a4.lb","t":"s-a separat de vehiculul-tractor și a continuat să se deplaseze.","lvl":2},{"k":"note","t":"[Art.14 al.(4) introdus prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"al","n":"5","id":"a5","t":"Asigurătorul RCA al vehiculului-tractor despăgubește partea prejudiciată și poate exercita dreptul de regres asupra asigurătorului RCA al remorcii sau al semiremorcii în cazul în care demonstrează că prejudiciul s-a produs ca urmare a unei defecțiuni tehnice a remorcii sau a semiremorcii, care nu putea fi identificată de către conducătorul vehiculului-tractor.","lvl":1},{"k":"note","t":"[Art.14 al.(5) introdus prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n2","lvl":0},{"k":"al","n":"6","id":"a6","t":"Pagubele produse de o remorcă sau o semiremorcă se acoperă de asigurarea obligatorie RCA a proprietarului ori a utilizatorului acesteia, dacă remorca sau semiremorca:","lvl":1},{"k":"lit","n":"a","id":"a6.la","t":"nu este tractată de vehiculul-tractor; ori","lvl":2},{"k":"lit","n":"b","id":"a6.lb","t":"este separată de vehiculul-tractor și staționează.","lvl":2},{"k":"note","t":"[Art.14 al.(6) introdus prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n3","lvl":0}]},{"id":"15","num":"15","title":"Categorii de persoane păgubite","node":"n6","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurarea obligatorie RCA acoperă răspunderea pentru pagubele produse de accidente de vehicule tuturor persoanelor altele decât conducătorul vehiculului culpabil.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Membrii familiei asiguratului, ai conducătorului de vehicul sau ai oricărei alte persoane a cărei răspundere civilă este angajată într-un accident de vehicul și este acoperită de asigurarea obligatorie RCA nu sunt excluși de la beneficiul asigurării pentru propriile lor vătămări corporale.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Asigurarea obligatorie RCA acoperă pagubele produse de accidente de vehicule pietonilor, cicliștilor și altor utilizatori nemotorizați ai drumurilor, care, în urma unui accident de vehicul, au dreptul la o despăgubire de asigurare în limitele de răspundere prevăzute de prezenta lege.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Prezentul articol nu aduce atingere răspunderii civile ori valorii despăgubirii de asigurare.","lvl":1}]},{"id":"16","num":"16","title":"Clauze contractuale de excludere","node":"n6","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurătorul RCA nu acordă despăgubiri de asigurare pentru:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"cazurile în care asiguratul nu este culpabil de producerea accidentului;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"cazurile în care accidentul a fost produs din culpa exclusivă a persoanei păgubite;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"cazurile în care accidentul a fost produs din culpa exclusivă a unei persoane terțe, cu excepția situațiilor prevăzute la art. 14 alin. (3) lit. d);","lvl":2,"r":[[122,147,{"art":"14","al":"3","lit":"d"}]]},{"k":"lit","n":"d","id":"a1.ld","t":"daunele produse bunurilor ce aparțin conducătorului vehiculului culpabil de producerea accidentului, precum și pentru vătămările corporale sau decesul acestuia, indiferent cine solicită aceste despăgubiri de asigurare;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"daunele produse bunurilor ce aparțin persoanei fizice sau juridice, dacă au fost provocate de un vehicul aflat în proprietatea și/sau în utilizarea aceleiași persoane fizice sau juridice, care a îndeplinit obligația de asigurare obligatorie RCA, și care este condus de un prepus al aceleiași persoane juridice ori de o altă persoană pentru care răspunde persoana fizică sau juridică;","lvl":2},{"k":"lit","n":"f","id":"a1.lf","t":"cazurile în care bunurile avariate sunt utilizate de către proprietarul și/sau utilizatorul vehiculului care a îndeplinit obligația de asigurare obligatorie RCA și care a produs pagubele;","lvl":2},{"k":"lit","n":"g","id":"a1.lg","t":"cazurile în care bunurile avariate și vehiculul al căror proprietar și/sau utilizator au îndeplinit obligația de asigurare obligatorie RCA fac parte din patrimoniul comun al soților;","lvl":2},{"k":"lit","n":"h","id":"a1.lh","t":"partea din pagubă care depășește limitele de răspundere stabilite prin contractul de asigurare obligatorie RCA, produsă în unul și același accident, indiferent de numărul persoanelor păgubite și de numărul persoanelor responsabile de producerea accidentului;","lvl":2},{"k":"lit","n":"i","id":"a1.li","t":"amenzile de orice fel și cheltuielile pentru procesul penal pe care ar fi obligat să le achite proprietarul, utilizatorul și/sau conducătorul vehiculului care au îndeplinit obligația de asigurare obligatorie RCA, responsabili de producerea accidentului;","lvl":2},{"k":"lit","n":"j","id":"a1.lj","t":"cheltuielile suportate pentru procesul penal de către proprietarul, utilizatorul și/sau conducătorul vehiculului care au a îndeplinit obligația de asigurare obligatorie RCA și sunt responsabili de producerea accidentului, chiar dacă în cadrul acestui proces s-a soluționat și latura civilă;","lvl":2},{"k":"lit","n":"k","id":"a1.lk","t":"sumele pe care conducătorul vehiculului culpabil de producerea accidentului este obligat să le plătească pentru avarierea ori distrugerea vehiculului proprietarului și/sau utilizatorului căruia i-a fost încredințat vehiculul și care au îndeplinit obligația de asigurare obligatorie RCA;","lvl":2},{"k":"lit","n":"l","id":"a1.ll","t":"pagubele produse bunurilor transportate, dacă între proprietarul, utilizatorul și/sau conducătorul vehiculului culpabil și persoanele păgubite a existat un contract de transport la data producerii accidentului;","lvl":2},{"k":"lit","n":"m","id":"a1.lm","t":"pagubele produse persoanelor sau bunurilor aflate în vehiculul care a produs accidentul, dacă asigurătorul RCA poate dovedi că persoanele păgubite cunoșteau că vehiculul respectiv era furat;","lvl":2},{"k":"lit","n":"n","id":"a1.ln","t":"pagubele produse de dispozitivele sau de instalațiile montate pe vehicul, care sunt utilizate ca instalații de lucru ori ca utilaje și constituie riscuri ale activității profesionale;","lvl":2},{"k":"lit","n":"o","id":"a1.lo","t":"pagubele produse de accidentele de vehicule survenite în timpul operațiilor de încărcare și de descărcare;","lvl":2},{"k":"lit","n":"p","id":"a1.lp","t":"pagubele produse în urma transportării de produse periculoase radioactive, ionizante, inflamabile, explozive, corozive, de combustibili, care au determinat producerea accidentului și agravarea pagubelor;","lvl":2},{"k":"lit","n":"q","id":"a1.lq","t":"pagubele cauzate prin utilizarea unui vehicul în timpul unui atac terorist sau în timpul războiului, dacă utilizarea are legătură directă cu respectivul atac ori război;","lvl":2},{"k":"lit","n":"r","id":"a1.lr","t":"reducerea valorii bunurilor după reparație;","lvl":2},{"k":"lit","n":"s","id":"a1.ls","t":"pagubele care au dus la poluarea mediului din cauza unui accident;","lvl":2},{"k":"lit","n":"t","id":"a1.lt","t":"pagubele produse în urma dispariției sau distrugerii valorilor mobiliare, a banilor, a pietrelor prețioase, a obiectelor din metale prețioase și pietre prețioase, a obiectelor de artă și a altor obiecte ale proprietății intelectuale;","lvl":2},{"k":"lit","n":"u","id":"a1.lu","t":"pagubele produse de exploatarea vehiculelor în cadrul întrecerilor și antrenamentelor sportive, organizate în locuri special prevăzute pentru acestea;","lvl":2},{"k":"lit","n":"v","id":"a1.lv","t":"pagubele produse în situațiile în care răspunderea asigurătorului RCA nu începuse, încetase ori era suspendată;","lvl":2},{"k":"lit","n":"w","id":"a1.lw","t":"pagubele care sunt consecința lipsei de folosință a vehiculului avariat, inclusiv a înlocuirii temporare a vehiculului, pe baza opțiunii persoanei păgubite;","lvl":2},{"k":"lit","n":"x","id":"a1.lx","t":"profitul sau venitul ratat.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Persoana păgubită are dreptul să înainteze în instanța de judecată o acțiune civilă împotriva persoanei culpabile de producerea accidentului în scopul recuperării daunelor excluse din asigurarea obligatorie RCA, conform alin. (1).","lvl":1,"r":[[220,229,{"al":"1","art":"16"}]]},{"k":"al","n":"3","id":"a3","t":"Nu pot beneficia de despăgubiri de asigurare persoanele care, la data producerii accidentului, au avut posibilitatea să își recupereze pagubele suportate în baza unei asigurări facultative sau obligatorii, cu excepția exercitării opțiunii prevăzute la art. 24 alin. (9), ori în baza legislației și persoanele care au urcat de bunăvoie în vehiculul condus de către persoana culpabilă de producerea accidentului, dacă se dovedește că acestea știau că pentru vehiculul respectiv nu era în vigoare un contract de asigurare obligatorie RCA.","lvl":1,"r":[[252,269,{"art":"24","al":"9"}]]}]},{"id":"17","num":"17","title":"Culpa comună","node":"n6","blocks":[{"k":"al","n":"1","id":"a1","t":"În situația în care persoana păgubită a contribuit, din culpă, la producerea accidentului sau la agravarea pagubei, aceasta va fi considerată responsabilă numai pentru partea din pagubă care îi este imputabilă. În astfel de cazuri, mărimea răspunderii fiecărei persoane va fi cea constatată prin orice mijloc de probă.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazul în care nu se poate stabili întinderea răspunderii fiecărei persoane, aceasta se va stabili în cote egale, în raport cu numărul părților implicate în accident, fiecare parte având dreptul la despăgubirea de asigurare în proporția în care nu s-a făcut responsabilă de producerea accidentului.","lvl":1}]},{"id":"18","num":"18","title":"Obligațiile asiguratului","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazul producerii accidentului de vehicul, asiguratul este obligat:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"să întreprindă toate acțiunile posibile pentru diminuarea pagubelor produse;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"să notifice organele de poliție sau alte organe de drept despre accidentul de vehicul (cu excepția accidentelor pasibile de documentarea prin procedura de constatare amiabilă a accidentului) imediat după producerea acestuia, solicitând întocmirea actelor referitoare la cauzele și circumstanțele producerii accidentului de vehicul, precum și la consecințele acestuia;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"în cazul aplicării procedurii de constatare amiabilă a accidentului de vehicul:","lvl":2},{"k":"dash","id":"d1","t":"să înștiințeze imediat asigurătorul RCA care a emis polița de asigurare obligatorie RCA sau BNAA-ul, în cazul deținerii certificatului de asigurare „Carte Verde”, despre producerea accidentului pe teritoriul Republicii Moldova;","lvl":3},{"k":"dash","id":"d2","t":"să documenteze, fără întârziere, circumstanțele producerii accidentului de vehicul în mod electronic, prin accesarea și utilizarea de către ambii conducători de vehicule implicați în accident a serviciului de constatare amiabilă a accidentului din cadrul aplicației guvernamentale integrate a serviciilor electronice, sau prin completarea și semnarea de către ambii conducători de vehicule implicați în accident a formularului „Constatare amiabilă de accident”;","lvl":3},{"k":"note","t":"[Art.18 al.(1), lit.c) liniuța a doua modificată prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"dash","id":"d3","t":"să înregistreze datele martorilor, dacă aceștia există;","lvl":3},{"k":"dash","id":"d4","t":"să facă fotografii și/sau imagini video la locul accidentului, care să cuprindă ambele vehicule accidentate, plăcile cu numerele de înmatriculare și părțile avariate ale acestora, care să fie vizibile, și urmele de frânare și de cioburi de la fața locului, dacă acestea există;","lvl":3},{"k":"dash","id":"d5","t":"să prezinte asigurătorului RCA, în termen de 2 zile lucrătoare de la data producerii accidentului, exemplarul său al formularului „Constatare amiabilă de accident”, completat și semnat de către ambii conducători de vehicule implicați în accident, cu excepția documentării cazului în mod electronic, prin intermediul aplicației guvernamentale integrate a serviciilor electronice;","lvl":3},{"k":"note","t":"[Art.18 al.(1), lit.c) liniuța a cincea modificată prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n2","lvl":0},{"k":"lit","n":"d","id":"a1.ld","t":"să înștiințeze, în termen de 48 de ore din momentul producerii accidentului, asigurătorul RCA care a emis polița de asigurare obligatorie RCA sau BNAA-ul, în cazul deținerii certificatului de asigurare „Carte Verde”, despre producerea accidentului pe teritoriul Republicii Moldova. Conducătorii vehiculelor implicați în accident, care dețin polițe de asigurare obligatorii RCA și/sau certificate de asigurare „Carte Verde”, indiferent de rezultatele constatării vinovăției, sunt obligați să nu întreprindă de sine stătător măsuri de înlăturare a pagubelor;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"să notifice persoanele implicate în accident și persoana păgubită sau apropiații acesteia despre faptul că deține poliță de asigurare obligatorie RCA și/sau certificat de asigurare „Carte Verde” și să ofere informațiile necesare despre asigurătorul RCA;","lvl":2},{"k":"lit","n":"f","id":"a1.lf","t":"să prezinte asigurătorului RCA ori reprezentantului de despăgubiri actul privind producerea accidentului, elaborat de organul de poliție și de instituțiile competente, permisul de conducere valabil pentru categoria din care face parte vehiculul, certificatul de înmatriculare și raportul de inspecție tehnică periodică a vehiculului care a provocat accidentul;","lvl":2},{"k":"lit","n":"g","id":"a1.lg","t":"să asigure, la solicitarea asigurătorului RCA, accesul la vehiculul cu care a provocat accidentul.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Refuzul asiguratului de a respecta prevederile alin. (1) nu limitează dreptul persoanei păgubite de a fi despăgubită. În acest caz, asigurătorul RCA are dreptul să înainteze împotriva asiguratului acțiune de regres privind cheltuielile suplimentare aferente neîndeplinirii prevederilor menționate.","lvl":1,"r":[[47,56,{"al":"1","art":"18"}]]},{"k":"al","n":"3","id":"a3","t":"Refuzul asiguratului de a se prezenta, la solicitarea asigurătorului RCA, în legătură cu acțiunea de regres, nu limitează dreptul persoanei păgubite de a fi despăgubită.","lvl":1}]},{"id":"19","num":"19","title":"Drepturile și obligațiile persoanei păgubite","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Asiguratul transmite persoanei păgubite, la cererea acesteia, informațiile necesare pentru formularea pretențiilor de despăgubire, în special:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"numele, prenumele și adresa conducătorului vehiculului în momentul producerii accidentului;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"denumirea și adresa sediului persoanei juridice posesoare a vehiculului;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"denumirea, adresa asigurătorului RCA care a emis contractul de asigurare obligatorie RCA, seria și numărul contractului, precum și numărul de înmatriculare/înregistrare al vehiculului ori numărul de identificare al acestuia.","lvl":2},{"k":"al","n":"2","id":"a2","t":"În cazul aplicării procedurii de constatare amiabilă a accidentului de vehicul, persoanei păgubite îi sunt opozabile obligațiile prevăzute la art. 18 alin. (1) lit. c).","lvl":1,"r":[[142,167,{"art":"18","al":"1","lit":"c"}]]},{"k":"al","n":"3","id":"a3","t":"Drepturile persoanei păgubite prin accidentul produs pe teritoriul Republicii Moldova de vehiculul aflat în proprietatea și/sau utilizarea asiguratului se exercită față de asigurătorul RCA al persoanei culpabile sau față de propriul asigurător RCA, în cazul decontării directe, sau prin reprezentantul de despăgubiri, în limitele de răspundere ale asigurării RCA prevăzute în prezenta lege.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Drepturile persoanei păgubite prin accidentul produs pe teritoriul Republicii Moldova de vehiculul aflat în proprietatea și/sau în utilizarea unei persoane asigurate în străinătate se exercită față de asigurătorul acestei persoane prin intermediul BNAA-ului, dacă sunt îndeplinite condițiile prevăzute la art. 4 alin. (4) lit. b).","lvl":1,"r":[[305,329,{"art":"4","al":"4","lit":"b"}]]},{"k":"al","n":"5","id":"a5","t":"Persoana păgubită are dreptul să înainteze o cerere de despăgubire către asigurătorul RCA al persoanei culpabile sau către propriul asigurător RCA, în cazul decontării directe, sau către reprezentantul de despăgubiri desemnat de acesta, indiferent dacă asiguratul a executat sau nu obligația de înștiințare prevăzută la art. 18 alin. (1) lit. d).","lvl":1,"r":[[320,345,{"art":"18","al":"1","lit":"d"}]]},{"k":"al","n":"6","id":"a6","t":"Asigurătorul RCA nu are dreptul să refuze examinarea și soluționarea cererii de despăgubire depuse în condițiile alin. (5).","lvl":1,"r":[[113,122,{"al":"5","art":"19"}]]},{"k":"al","n":"7","id":"a7","t":"Drepturile persoanei păgubite într-un accident de vehicule se exercită față de BNAA, iar despăgubirile de asigurare se plătesc în limitele de răspundere stabilite la art. 13 și în condițiile prevăzute la art. 39 alin. (3) dacă:","lvl":1,"r":[[166,173,{"art":"13"}],[204,221,{"art":"39","al":"3"}]]},{"k":"lit","n":"a","id":"a7.la","t":"vehiculul și/sau conducătorul acestuia au fost identificați și s-a stabilit că conducătorul nu a îndeplinit obligația de încheiere a contractului de asigurare obligatorie RCA și/sau vehiculele nu sunt înregistrate sau nu au fost supuse înmatriculării pe teritoriul Republicii Moldova;","lvl":2},{"k":"lit","n":"b","id":"a7.lb","t":"vehiculul și/sau conducătorul acestuia au rămas neidentificați;","lvl":2},{"k":"lit","n":"c","id":"a7.lc","t":"dacă vehiculul a fost obținut pe cale ilicită;","lvl":2},{"k":"lit","n":"d","id":"a7.ld","t":"accidentul a avut loc în perioada suspendării contractului de asigurare obligatorie RCA pentru vehicul, indiferent de persoana care a cauzat accidentul.","lvl":2},{"k":"al","n":"8","id":"a8","t":"În cazurile prevăzute la alin. (7), drepturile și obligațiile aferente dosarului de daune, constatarea pagubelor, stabilirea și plata despăgubirilor de asigurare, prevăzute de prezenta lege pentru asigurătorul RCA, se vor atribui și BNAA-ului.","lvl":1,"r":[[25,34,{"al":"7","art":"19"}]]},{"k":"al","n":"9","id":"a9","t":"Persoana păgubită este obligată să asigure, în termenul specificat la art. 20 alin. (1) lit. d), accesul asigurătorului RCA sau al reprezentantului de despăgubiri desemnat de acesta la bunurile avariate în accidentul de vehicul, astfel încât asigurătorul RCA să poată constata valoarea reală a pagubelor.","lvl":1,"r":[[70,95,{"art":"20","al":"1","lit":"d"}]]},{"k":"al","n":"10","id":"a10","t":"Dacă persoana păgubită nu a respectat obligația prevăzută la alin. (9) și a făcut imposibilă întocmirea dosarului de daune și/sau constatarea de către asigurătorul RCA a întinderii pagubelor, acesta din urmă este absolvit de obligația de a plăti despăgubirea de asigurare.","lvl":1,"r":[[61,70,{"al":"9","art":"19"}]]},{"k":"al","n":"11","id":"a11","t":"Prin derogare de la alin. (9) și (10) al prezentului articol și art. 24 alin. (11), în cazul în care în drepturile persoanei păgubite în accidentul produs pe teritoriul Republicii Moldova s-a subrogat asigurătorul de bunuri dintr-un stat terț, asigurătorul RCA constată pagubele și plătește despăgubirile de asigurare în condițiile prezentei legi și în baza documentelor justificative prezentate de către asigurătorul de bunuri din statul terț.","lvl":1,"r":[[20,29,{"al":"9","art":"19"}],[33,37,{"al":"10","art":"19"}],[64,82,{"art":"24","al":"11"}]]},{"k":"al","n":"12","id":"a12","t":"Prin derogare de la alin. (9) și (10), asigurătorul va plăti despăgubirea de asigurare în cazul bunurilor de importanță socială și/sau de securitate a traficului rutier (piloni de electricitate, instalații de gaze naturale, parapete de la marginea carosabilului, semafoare, alte obiecte care privesc securitatea traficului rutier) avariate și înlocuite imediat după producerea accidentelor de vehicule, cu condiția realizării fotografiilor și/sau a imaginilor video panoramice și în detaliu ale bunurilor și ale părților avariate ale acestora și cu condiția depozitării ulterioare într-un spațiu corespunzător pentru examinarea și stabilirea întinderii pagubelor de către asigurătorul RCA sau de către BNAA, după caz, în scopul plătirii despăgubirilor de asigurare.","lvl":1,"r":[[20,29,{"al":"9","art":"19"}],[33,37,{"al":"10","art":"19"}]]}]},{"id":"20","num":"20","title":"Drepturile și obligațiile asigurătorului RCA","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"După ce a luat cunoștință de producerea accidentului, asigurătorul RCA este obligat:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"să deschidă un dosar de daune;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"să examineze formularul „Constatare amiabilă de accident”, completat în modul prevăzut de prezenta lege, prezentat de către persoana păgubită și anexat la cererea de despăgubire, precum și să emită fără întârziere documentul care confirmă recepționarea și înregistrarea cererii de despăgubire;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"să solicite instituțiilor subordonate ale Ministerului Afacerilor Interne, organelor de drept și instanțelor judecătorești, instituțiilor medicale și altor persoane juridice de drept public și privat informațiile necesare pentru instrumentarea dosarului de daune sau pentru exercitarea dreptului de regres de către asigurătorul RCA, stipulate în prezenta lege, (cu excepția accidentelor documentate, cu respectarea procedurii de constatare amiabilă), dacă asiguratul sau persoana păgubită nu a prezentat asigurătorului RCA astfel de informații certificate în modul corespunzător. În cazul în care informația necesară se regăsește în Registrul de stat al accidentelor rutiere, aceasta este obținută de către asigurătorul RCA prin intermediul platformei de interoperabilitate (MConnect), direct din registrul menționat;","lvl":2},{"k":"note","t":"[Art.20 al.(1), lit.c) modificată prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"lit","n":"d","id":"a1.ld","t":"să examineze bunurile avariate și să întocmească, în termen de până la 5 zile lucrătoare de la data primirii cererii de despăgubire depuse de persoana păgubită, un proces-verbal de constatare a pagubelor;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"să închidă dosarul de daune privind pagubele produse de accidentul de vehicul în cel mult 30 de zile de la data depunerii de către persoana păgubită a ultimului document necesar finalizării dosarului;","lvl":2},{"k":"lit","n":"f","id":"a1.lf","t":"să plătească despăgubirea de asigurare în termenele stabilite de prezenta lege.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Asigurătorul RCA este obligat să ia o decizie cu privire la soluționarea cererii de despăgubire și să plătească despăgubirea de asigurare în cel mult 30 de zile de la data depunerii cererii de despăgubire – în cazul dosarului de daune complet și în cel mult 90 de zile – în cazul dosarului de daune incomplet. Decizia cu privire la soluționarea cererii de despăgubire se comunică persoanei păgubite în termen de 5 zile lucrătoare de la data adoptării, în mod obligatoriu, cu confirmarea expedierii.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul în care asiguratul contestă în instanța de judecată actele emise de către organele de constatare a circumstanțelor producerii cazului asigurat, inclusiv deciziile adoptate referitoare la stabilirea culpei asiguratului în producerea cazului asigurat, și informează asigurătorul RCA cu privire la aceasta, asigurătorul RCA are dreptul să suspende examinarea cererii de despăgubire în partea ce ține de plătirea despăgubirii de asigurare până la emiterea hotărârii judecătorești definitive privind stabilirea culpei.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Dacă asigurătorul RCA nu își îndeplinește obligațiile în termenul prevăzut la alin. (2) sau le îndeplinește necorespunzător, inclusiv dacă diminuează nejustificat despăgubirea de asigurare, acestuia i se aplică o penalitate de 0,1% pentru fiecare zi de întârziere, calculată pe baza sumei totale de despăgubire cuvenită sau a diferenței de sumă neplătită. Plata penalităților se face odată cu plata despăgubirii de asigurare.","lvl":1,"r":[[78,87,{"al":"2","art":"20"}]]},{"k":"al","n":"5","id":"a5","t":"Pe durata suspendării examinării cererii de despăgubire în condițiile alin. (3) și pe perioada în care accidentul de vehicul face obiectul unui proces judiciar privind stabilirea culpei, prevederile alin. (4) nu se aplică.","lvl":1,"r":[[70,79,{"al":"3","art":"20"}],[199,208,{"al":"4","art":"20"}]]}]},{"id":"21","num":"21","title":"Constatarea amiabilă a accidentului de vehicul","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Procedura de constatare amiabilă a accidentului de vehicul (în continuare –procedură de constatare amiabilă) este o soluție de constatare a faptelor, a circumstanțelor și a persoanei culpabile de producerea accidentului, alternativă procedurii aplicate de angajații organelor de poliție, ai unităților de pompieri și ai procuraturii, și este aplicabilă doar cu condiția exprimării benevole a voinței ambilor conducători de vehicule implicați în accident.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Procedura de constatare amiabilă constă în completarea și semnarea de către conducătorii de vehicule implicați în accident a formularului „Constatare amiabilă de accident”, cu indicarea persoanei care își asumă responsabilitatea de producerea accidentului, care, ulterior, este prezentat asigurătorului RCA al persoanei presupuse responsabile de accident împreună cu cererea de despăgubire.","lvl":1},{"k":"al","n":"2¹","id":"a2_1","t":"Dacă ambii conducători de vehicule se pot identifica electronic utilizând serviciile de încredere, procedura de constatare amiabilă poate fi realizată în mod electronic, prin accesarea și utilizarea de către ambii conducători de vehicule implicați în accident a serviciului de constatare amiabilă a accidentului din cadrul aplicației guvernamentale integrate a serviciilor electronice, cu indicarea persoanei care își asumă responsabilitatea de producerea accidentului de vehicul. Constatarea amiabilă realizată în mod electronic și cererea de despăgubire electronică se remit, în mod automatizat, din aplicația guvernamentală integrată a serviciilor electronice, prin intermediul platformei de interoperabilitate (MConnect), asigurătorului RCA al persoanei presupuse responsabile de accident și, după caz, asigurătorului cu care persoana păgubită are încheiat un contract de asigurare de bunuri.","lvl":1},{"k":"note","t":"[Art.21 al.(2¹) introdus prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"al","n":"3","id":"a3","t":"Procedura de constatare amiabilă se aplică cu respectarea cumulativă a următoarelor condiții:","lvl":1},{"k":"lit","n":"a","id":"a3.la","t":"în accident sunt implicate doar două vehicule (inclusiv ansamblul format din vehiculul-tractor și remorca sau semiremorca tractată de acesta);","lvl":2},{"k":"note","t":"[Art.21 al.(3), lit.a) în redacția LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n2","lvl":0},{"k":"lit","n":"b","id":"a3.lb","t":"accidentul este soldat cu daune materiale nesemnificative în limita prevăzută la art. 13 alin. (1) lit. c);","lvl":2,"r":[[81,106,{"art":"13","al":"1","lit":"c"}]]},{"k":"lit","n":"c","id":"a3.lc","t":"accidentul nu s-a soldat cu vătămări corporale și/sau cu deteriorarea bunurilor (instalații rutiere, piloni, garduri, clădiri etc.) altele decât vehiculele implicate în accident;","lvl":2},{"k":"lit","n":"d","id":"a3.ld","t":"ambii conducători de vehicule implicați în accident își exprimă consimțământul privind documentarea accidentului prin procedura de constatare amiabilă și consensul privind circumstanțele producerii accidentului și daunele vizibile cauzate vehiculelor implicate, iar persoana responsabilă de producerea accidentului își recunoaște culpa;","lvl":2},{"k":"lit","n":"e","id":"a3.le","t":"conducătorii de vehicule implicați în accidentul de vehicul au posibilitatea de a realiza ori de a prezenta înregistrări foto și/sau video de la locul accidentului respectiv, conform cerințelor prevăzute la art. 18 alin. (1) lit. c) liniuța a patra;","lvl":2,"r":[[207,232,{"art":"18","al":"1","lit":"c"}]]},{"k":"note","t":"[Art.21 al.(3), lit.e) în redacția LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n3","lvl":0},{"k":"lit","n":"f","id":"a3.lf","t":"conducătorii de vehicule implicați în accident înregistrează datele martorilor dacă este posibil acest lucru.","lvl":2},{"k":"p","id":"a3.x1","t":"În cazul neîndeplinirii cumulative a condițiilor menționate la alin. (3) lit. a) și lit. c)–f), formularul „Constatare amiabilă de accident”, completat și semnat de către conducătorii de vehicule implicați în accident, devine nul, iar accidentul de vehicul urmează a fi documentat de către organele competente.","lvl":1,"cont":true,"r":[[63,80,{"al":"3","lit":"a","art":"21"}],[84,94,{"lit":"c","lit2":"f","art":"21","al":"3"}]]},{"k":"al","n":"4","id":"a4","t":"Forma și conținutul formularului „Constatare amiabilă de accident”, precum și normele privind utilizarea acestui formular, se aprobă de către Comisia Națională a Pieței Financiare, cu avizul organelor de poliție. Se interzice introducerea în formularul respectiv a informațiilor altele decât cele prevăzute în actele normative ale Comisiei Naționale a Pieței Financiare.","lvl":1},{"k":"note","t":"[Art.21 al.(4) modificat prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n4","lvl":0},{"k":"al","n":"5","id":"a5","t":"Formularul „Constatare amiabilă de accident” prevede, în mod obligatoriu, informațiile despre circumstanțele producerii accidentului, datele de identificare ale conducătorilor și ale vehiculelor implicate în accident, datele din polița de asigurare obligatorie RCA și/sau certificatul de asigurare „Carte Verde” (în cazul vehiculului aflat în proprietatea și/sau în utilizarea unei persoane asigurate în străinătate), datele despre daunele produse vehiculelor implicate, precum și alte informații stabilite în actele normative ale Comisiei Naționale a Pieței Financiare. Formularul „Constatare amiabilă de accident” se eliberează, în mod gratuit, asiguratului concomitent cu polița de asigurare obligatorie RCA sau la solicitare.","lvl":1},{"k":"note","t":"[Art.21 al.(5) modificat prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n5","lvl":0},{"k":"al","n":"5¹","id":"a5_1","t":"Modalitatea de realizare a constatării amiabile a accidentului în mod electronic prin intermediul aplicației guvernamentale integrate a serviciilor electronice se aprobă de către Comisia Națională a Pieței Financiare, cu avizul posesorului aplicației respective. Constatarea amiabilă a accidentului în mod electronic prevede, în mod obligatoriu, introducerea informațiilor stabilite la alin. (5) și consimțământul ambilor conducători de vehicule exprimat prin intermediul aplicației guvernamentale integrate a serviciilor electronice.","lvl":1,"r":[[386,395,{"al":"5","art":"21"}]]},{"k":"note","t":"[Art.21 al.(5¹) introdus prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n6","lvl":0},{"k":"al","n":"6","id":"a6","t":"În cazul aplicării procedurii de constatare amiabilă, cererea de despăgubire se remite, în mod automatizat, asigurătorului RCA în condițiile stabilite la alin. (2¹) sau se depune de către persoana păgubită la asigurătorul RCA al persoanei culpabile sau către propriul asigurător RCA, în cazul decontării directe, cu anexarea formularului „Constatare amiabilă de accident”, completat și semnat de către ambele părți, în baza acestuia fiind deschis dosarul de daune.","lvl":1,"r":[[154,164,{"al":"2_1","art":"21"}]]},{"k":"note","t":"[Art.21 al.(6) modificat prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n7","lvl":0},{"k":"al","n":"7","id":"a7","t":"În cazul accidentului de vehicul documentat prin procedura de constatare amiabilă, asigurătorul RCA are dreptul să refuze plătirea despăgubirii de asigurare dacă nu au fost întrunite condițiile prevăzute la alin. (3) din prezentul articol, cu excepția condiției de la lit. b) a alineatului menționat, caz în care asigurătorul RCA plătește despăgubirea de asigurare în limita prevăzută la art. 13 alin. (1) lit. c). Refuzul asigurătorului RCA de a plăti despăgubirea de asigurare nu limitează dreptul părților de a se adresa organelor sau instituțiilor competente pentru stabilirea circumstanțelor accidentului de vehicul și de a înainta, în baza documentelor de constatare, întocmite de aceste organe sau instituții, o cerere suplimentară de despăgubire, în modul prevăzut de prezenta lege.","lvl":1,"r":[[207,216,{"al":"3","art":"21"}],[268,275,{"lit":"b","art":"21","al":"7"}],[388,413,{"art":"13","al":"1","lit":"c"}]]},{"k":"al","n":"8","id":"a8","t":"Asigurătorul RCA are dreptul să refuze plătirea despăgubirii de asigurare dacă formularul „Constatare amiabilă de accident” este completat în mod ilizibil, este incomplet și conține date contradictorii sau eronate, cu excepția cazului în care asiguratul sau persoana păgubită a contribuit la înlăturarea erorilor.","lvl":1},{"k":"al","n":"9","id":"a9","t":"În cazul în care asigurătorul RCA nu este de acord că persoana identificată este recunoscută ca fiind responsabilă de accident în baza formularului „Constatare amiabilă de accident” sau în cazul în care asiguratul își retrage admiterea responsabilității, asigurătorul RCA plătește despăgubirea de asigurare în termenele stabilite de prezenta lege și are dreptul să solicite instanței de judecată, în termen de 15 zile de la data plătirii despăgubirii de asigurare, examinarea în fond a formularului „Constatare amiabilă de accident” și stabilirea persoanei responsabile de comiterea accidentului.","lvl":1},{"k":"note","t":"[Art.21 al.(9) modificat prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n8","lvl":0},{"k":"al","n":"10","id":"a10","t":"Dosarul de daună deschis în urma accidentului de vehicul, documentat prin procedura de constatare amiabilă, se instrumentează conform procedurii generale prevăzute de prezenta lege.","lvl":1},{"k":"al","n":"11","id":"a11","t":"Organele și instituțiile competente pentru stabilirea circumstanțelor accidentului de vehicul nu au dreptul să refuze întocmirea dosarului contravențional în condițiile Codului contravențional în cazul în care formularul „Constatare amiabilă de accident”, completat și semnat de către conducătorii de vehicule implicați în accident, devine nul.","lvl":1,"r":[[169,192,{"a":"cod:contraventional","whole":true}]]}]},{"id":"22","num":"22","title":"Dosarul de daune. Stabilirea pagubelor","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazul producerii unui caz acoperit prin asigurarea obligatorie RCA, persoana păgubită are dreptul să depună cererea de despăgubire la asigurătorul RCA al persoanei culpabile sau la asigurătorul propriu RCA, în cazul decontării directe, sau la BNAA, în cazul apariției unui risc acoperit de acesta, în condițiile prevăzute de prezenta lege.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Forma și conținutul cererii de despăgubire sunt unice pentru toți asigurătorii RCA și se stabilesc prin actele normative ale Comisiei Naționale a Pieței Financiare. Cererea de despăgubire poate fi completată și prin utilizarea mijloacelor electronice.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Odată cu deschiderea dosarului de daune, asigurătorul RCA sau, după caz, BNAA eliberează persoanei păgubite, în scris, lista documentelor necesare, dar nu mai multe decât cele menționate la alin. (4), pentru închiderea dosarului de daune și pentru plata despăgubirii.","lvl":1,"r":[[190,199,{"al":"4","art":"22"}]]},{"k":"al","n":"4","id":"a4","t":"În dosarul de daune se includ în mod obligatoriu următoarele documente:","lvl":1},{"k":"lit","n":"a","id":"a4.la","t":"documentele de constatare a faptelor și a circumstanțelor în care s-a produs accidentul de vehicul, prezentate pe suport de hârtie, în formă electronică ori cu convertirea documentației respective într-un format electronic ușor accesibil, inclusiv cu utilizarea semnăturii electronice simple, întocmite de către angajații organelor de poliție, ai unităților de pompieri, ai procuraturii, ai instituțiilor medicale, sau, după caz, formularul „Constatare amiabilă de accident” însoțit de înregistrări foto și/sau video de la locul accidentului de vehicul;","lvl":2},{"k":"note","t":"[Art.22 al.(4), lit.a) în redacția LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"lit","n":"b","id":"a4.lb","t":"explicația asiguratului sau utilizatorului de vehicul privind producerea accidentului, cu excepția cazurilor de vătămări corporale grave ori de deces al acestora în urma accidentului sau de eschivare de la răspundere;","lvl":2},{"k":"lit","n":"c","id":"a4.lc","t":"cererea persoanei păgubite privind constatarea pagubei și plătirea despăgubirii de asigurare;","lvl":2},{"k":"lit","n":"d","id":"a4.ld","t":"procesul-verbal de constatare a pagubelor;","lvl":2},{"k":"lit","n":"e","id":"a4.le","t":"procesul-verbal suplimentar de constatare a pagubelor, după caz;","lvl":2},{"k":"lit","n":"f","id":"a4.lf","t":"devizul cheltuielilor de reparație și/sau de înlocuire a părților sau pieselor avariate, cu indicarea prețurilor, întocmit prin intermediul sistemului informațional automatizat de evaluare în domeniul auto sau de către o unitate de reparații acceptată de părți;","lvl":2},{"k":"lit","n":"g","id":"a4.lg","t":"documentele care confirmă efectuarea reparațiilor, înlocuirea pieselor avariate și costul acestora, întocmite de către unitatea de reparații acceptată de părți, după caz;","lvl":2},{"k":"lit","n":"h","id":"a4.lh","t":"documentele care confirmă producerea vătămărilor corporale sau decesul;","lvl":2},{"k":"lit","n":"i","id":"a4.li","t":"hotărârea judecătorească definitivă privind plătirea despăgubirilor de asigurare, după caz;","lvl":2},{"k":"lit","n":"j","id":"a4.lj","t":"copiile de pe documentele primare, care confirmă plata despăgubirilor de asigurare;","lvl":2},{"k":"lit","n":"k","id":"a4.lk","t":"confirmarea scrisă a persoanei păgubite cu privire la lipsa pretențiilor față de asigurătorul RCA. Confirmarea trebuie să fie întocmită în două exemplare semnate, câte un exemplar pentru fiecare parte, cu excepția cazurilor prevăzute la art. 29 alin. (3);","lvl":2,"r":[[237,254,{"art":"29","al":"3"}]]},{"k":"lit","n":"l","id":"a4.ll","t":"angajamentul scris prin care persoana păgubită se obligă să restituie despăgubirea de asigurare, în cazul anulării actelor întocmite de către angajații organelor de poliție, ai unității de pompieri, ai procuraturii, ai instituțiilor medicale sau în cazul anulării formularului „Constatare amiabilă de accident”, după caz.","lvl":2},{"k":"al","n":"5","id":"a5","t":"În cazul în care asigurătorul RCA nu a examinat bunurile avariate și nu a încheiat un proces-verbal de constatare a pagubelor în termenul specificat la art. 20 alin. (1) lit. d), persoana păgubită are dreptul să apeleze la serviciile experților judiciari, ale entităților înregistrate și autorizate să efectueze expertize auto merceologice și auto tehnice sau ale unităților de reparații pentru constatarea pagubelor, fără a prezenta asigurătorului RCA bunurile avariate.","lvl":1,"r":[[152,177,{"art":"20","al":"1","lit":"d"}]]},{"k":"al","n":"6","id":"a6","t":"Procesul-verbal de constatare a pagubelor se încheie de către asigurătorul RCA, cu invitarea obligatorie a asiguratului, a proprietarului și/sau a utilizatorului de vehicul responsabil de producerea accidentului, precum și a persoanei păgubite, și se semnează de către persoanele prezente la întocmirea acestuia. Reprezentanții de despăgubiri sunt obligați să informeze persoanele respective cu privire la dreptul acestora de a consemna obiecții în procesul-verbal.","lvl":1},{"k":"note","t":"[Art.22 al.(6) în redacția LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n2","lvl":0},{"k":"al","n":"7","id":"a7","t":"Eventualele obiecții ale părților cu privire la evaluarea pagubelor constatate se menționează în procesul-verbal sau într-o anexă la acesta. Forma și conținutul procesului-verbal de constatare a pagubelor sunt unice pentru toți asigurătorii RCA și se stabilesc prin actele normative ale Comisiei Naționale a Pieței Financiare.","lvl":1},{"k":"al","n":"8","id":"a8","t":"După finalizarea dosarului de daune, asigurătorul RCA este obligat să elibereze, la solicitarea persoanei păgubite, în termen de 5 zile, un extras din dosarul de daune, în care să indice numărul dosarului deschis, piesele constatate ca fiind avariate în accident și soluțiile tehnice adoptate (reparație și/sau înlocuire).","lvl":1},{"k":"al","n":"9","id":"a9","t":"Persoana păgubită are dreptul să examineze toate documentele din dosarul de daune, indiferent dacă a fost semnat acordul de despăgubire.","lvl":1},{"k":"al","n":"10","id":"a10","t":"Dacă se modifică sau se schimbă soluțiile tehnice adoptate sau dacă în timpul demontării sau reparației bunului avariat se descoperă și alte pagube produse de accident care nu au putut fi constatate inițial, se încheie un proces-verbal suplimentar de constatare a pagubelor, în condițiile alin. (6) din prezentul articol, ale art. 19 alin. (9) și ale art. 20 alin. (1) lit. d).","lvl":1,"r":[[289,298,{"al":"6","art":"22"}],[326,343,{"art":"19","al":"9"}],[351,376,{"art":"20","al":"1","lit":"d"}]]},{"k":"note","t":"[Art.22 al.(10) modificat prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n3","lvl":0},{"k":"al","n":"11","id":"a11","t":"După finalizarea dosarului de daune și la solicitarea persoanei păgubite, asigurătorul RCA prezintă acesteia actul de evaluare sau devizul cheltuielilor de reparație și/sau de înlocuire a părților componente ori a pieselor avariate, cu indicarea prețurilor, sau alte documente în baza cărora a stabilit cuantumul despăgubirii de asigurare.","lvl":1}]},{"id":"23","num":"23","title":"Informația despre accident","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Instituțiile subordonate ale Ministerului Afacerilor Interne, organele de drept și instanțele judecătorești, instituțiile medicale și alte persoane juridice de drept public și privat, care dispun de informațiile necesare pentru instrumentarea dosarului de daune sau pentru exercitarea dreptului de regres al asigurătorului RCA, prezintă, în mod obligatoriu, asiguratului și/sau persoanei păgubite documente și date, pe suport de hârtie, în formă electronică ori cu convertirea documentației respective într-un format electronic ușor accesibil, inclusiv cu utilizarea semnăturii electronice simple, în mod gratuit și în termen de 15 zile lucrătoare, la cererea asigurătorului RCA. În cazul în care informația necesară se regăsește în Registrul de stat al accidentelor rutiere, aceasta este obținută de către asigurătorul RCA prin intermediul platformei de interoperabilitate (MConnect), direct din registrul menționat.","lvl":1},{"k":"note","t":"[Art.23 al.(1) în redacția LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"al","n":"2","id":"a2","t":"Ministerul Afacerilor Interne, Agenția Servicii Publice și Agenția Națională Transport Auto prezintă informațiile necesare pentru buna funcționare a Sistemului informațional automatizat de stat în domeniul asigurărilor obligatorii RCA în mod continuu și în timp util.","lvl":1}]},{"id":"24","num":"24","title":"Stabilirea despăgubirilor și indemnizațiilor de asigurare","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Cuantumul despăgubirii de asigurare se stabilește în baza unui acord încheiat între persoana păgubită și asigurătorul RCA, întocmit pe suport de hârtie, în formă scrisă, sau prin mijloace electronice. În cazul în care părțile nu au ajuns la nicio înțelegere, asigurătorul RCA plătește despăgubirea de asigurare în cuantumul stabilit, iar persoana păgubită are dreptul să conteste decizia asigurătorului în instanța de judecată.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazul stabilirii cuantumului despăgubirii de asigurare prin hotărâre judecătorească, drepturile persoanei păgubite în accidentul de vehicul aflat în proprietatea și/sau în utilizarea unui asigurat din Republica Moldova se exercită față de asigurătorul RCA, în limitele obligației acestuia, conform prezentei legi.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Acordul încheiat între persoana păgubită și asigurătorul RCA are caracter total, necondiționat, definitiv și stinge toate pretențiile ce decurg din pagubele care existau sau puteau fi cunoscute la data încheierii acordului pentru pagubele ce s-au acoperit pe această cale, cu excepția cazului în care, ulterior plății despăgubirii pentru vătămări corporale, starea de sănătate a persoanei păgubite s-a agravat ori a intervenit decesul acesteia ca urmare a aceluiași accident.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În cazul în care accidentul de vehicul face obiectul unui proces penal, despăgubirile de asigurare pot fi stabilite în baza unui acord între persoana păgubită și asigurătorul RCA, înainte de data pronunțării unei sentințe definitive și irevocabile, cu condiția că această culpă nu trezește îndoieli.","lvl":1},{"k":"al","n":"5","id":"a5","t":"În cazul avarierii sau distrugerii de bunuri, despăgubirile de asigurare se stabilesc în conformitate cu prezenta lege, ținându-se cont de pretențiile formulate de către persoana păgubită, fără a se depăși diferența dintre valoarea acestor bunuri la momentul producerii accidentului și valoarea rămasă și limita maximă a despăgubirilor de asigurare prevăzută de prezenta lege.","lvl":1},{"k":"al","n":"6","id":"a6","t":"În cuantumul despăgubirilor de asigurare se includ următoarele cheltuieli suportate de persoana păgubită pentru:","lvl":1},{"k":"lit","n":"a","id":"a6.la","t":"acțiunile de diminuare a pagubelor;","lvl":2},{"k":"lit","n":"b","id":"a6.lb","t":"transportarea bunurilor la locul de reparație ori la parcare sau depozitare;","lvl":2},{"k":"lit","n":"c","id":"a6.lc","t":"cazul asigurat și procesul civil;","lvl":2},{"k":"lit","n":"d","id":"a6.ld","t":"expertiza tehnică efectuată la cererea acesteia, conform art. 22 alin. (5).","lvl":2,"r":[[57,74,{"art":"22","al":"5"}]]},{"k":"al","n":"7","id":"a7","t":"Cheltuielile enumerate la alin. (6) se rambursează doar în cazul prezentării documentelor justificative.","lvl":1,"r":[[26,35,{"al":"6","art":"24"}]]},{"k":"al","n":"8","id":"a8","t":"Dacă, în cazul avarierii sau distrugerii bunurilor, autoritățile publice competente nu au stabilit elemente determinante cu privire la cauzele și împrejurările producerii accidentului de vehicul ori la pagubele cauzate, aceste elemente pot fi dovedite de părțile interesate, folosindu-se orice metodă prevăzută de legislație.","lvl":1},{"k":"note","t":"[Art.24 al.(8) modificat prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"al","n":"9","id":"a9","t":"Dacă, la data producerii accidentului de vehicul, persoana păgubită are în vigoare un contract de asigurare de bunuri pentru bunurile avariate sau distruse prin accidentul de vehicul, aceasta poate opta pentru a fi despăgubită în temeiul acelui contract sau în temeiul contractului de asigurare obligatorie RCA.","lvl":1},{"k":"al","n":"10","id":"a10","t":"În cazul în care persoana păgubită se adresează asigurătorului cu care are încheiat un contract de asigurare de bunuri în scopul recuperării pagubelor, constatarea circumstanțelor accidentului de vehicul, soluțiile tehnice adoptate, evaluarea și stabilirea despăgubirilor de asigurare vor fi opozabile asigurătorului RCA al persoanei culpabile care deține contract de asigurare obligatorie RCA, în limitele prevederilor prezentei legi, dacă asigurătorul de bunuri a respectat procedura de invitare a asigurătorului RCA al persoanei culpabile, prevăzută la alin. (11).","lvl":1,"r":[[556,566,{"al":"11","art":"24"}]]},{"k":"al","n":"11","id":"a11","t":"Asigurătorul care are încheiat un contract de asigurare de bunuri cu persoana păgubită este obligat să invite la procesul de constatare a pagubei persoana culpabilă și asigurătorul RCA al acesteia, probând invitația printr-un document justificativ. Neprezentarea asigurătorului RCA al persoanei culpabile la data și locul stabilit nu împiedică asigurătorul de bunuri să constate și să evalueze pagubele ce vor fi opozabile asigurătorului RCA absent de la procesul de constatare, în limitele prevederilor prezentei legi.","lvl":1},{"k":"al","n":"12","id":"a12","t":"Pentru respectarea prevederilor alin. (11), asigurătorul cu care persoana păgubită are încheiat un contract de asigurare de bunuri recuperează de la asigurătorul RCA al persoanei culpabile despăgubirea de asigurare plătită persoanei păgubite, în limitele stabilite de prezenta lege, pentru unul și același accident de vehicul.","lvl":1,"r":[[32,42,{"al":"11","art":"24"}]]}]},{"id":"25","num":"25","title":"Stabilirea despăgubirilor de asigurare în cazul avarierii sau distrugerii vehiculului","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Despăgubirea de asigurare pentru avarierea sau distrugerea vehiculului nu poate depăși:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"valoarea pagubei real suportate;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"diferența dintre valoarea vehiculului la data producerii accidentului și valoarea rămasă;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"limita despăgubirii de asigurare prevăzută de prezenta lege.","lvl":2},{"k":"al","n":"2","id":"a2","t":"În cazul daunei totale, valorile menționate la alin. (1) lit. b) sunt determinate de către asigurătorul RCA prin personalul propriu sau prin servicii externalizate efectuate de către o entitate înregistrată și autorizată să efectueze expertize auto merceologice și auto tehnice. Persoana păgubită poate opta pentru repararea vehiculului în limita valorii determinate conform alin. (1) lit. b), dacă cerințele tehnice permit repararea vehiculului, sau poate opta pentru soluționarea cazului ca daună totală prin plata diferenței dintre valoarea vehiculului și valoarea rămasă.","lvl":1,"r":[[47,64,{"al":"1","lit":"b","art":"25"}],[375,392,{"al":"1","lit":"b","art":"25"}]]},{"k":"al","n":"3","id":"a3","t":"În cazul daunei parțiale, valoarea pagubei real suportate de vehicul este egală cu costul reparației părților componente sau al pieselor avariate ori, dacă este necesar, cu costul de înlocuire a acestora, inclusiv cu cheltuielile pentru materiale, pentru lucrările de demontare și asamblare aferente reparațiilor și/sau înlocuirilor necesare.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Prin părți componente sau piese care trebuie înlocuite se înțeleg cele a căror reparație sau folosință nu mai este posibilă din punct de vedere tehnic, din cauza gradului înalt de avariere, ori cele a căror reparație este posibilă, dar costul acesteia, inclusiv cheltuielile pentru materiale, pentru demontare și asamblare, depășește valoarea de nou a părții componente sau a piesei respective.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Costul reparației vehiculului se stabilește în baza documentelor eliberate de către unitatea de reparații acceptată de părți.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Se consideră necesară revopsirea integrală a vehiculului atunci când minimum 50% din suprafața exterioară totală a vehiculului este avariată.","lvl":1},{"k":"al","n":"7","id":"a7","t":"Prețurile materialelor, ale părților componente și ale pieselor înlocuitoare sunt cele practicate de către unitățile de reparații.","lvl":1},{"k":"al","n":"8","id":"a8","t":"În cazul în care părțile componente, piesele sau materialele necesare pentru repararea vehiculului sunt cumpărate în valută străină, costul acestora este egal cu costul de achiziție prevăzut în actele de cheltuieli prezentate, inclusiv cheltuieli de transport, taxe vamale și taxa pe valoarea adăugată aferentă, echivalent în lei la cursul oficial de schimb al leului moldovenesc, valabil la data plății facturii. În astfel de cazuri, costul părților componente, al pieselor sau al materialelor (cu condiția că acestea sunt comercializate în Republica Moldova) nu va depăși prețul de vânzare practicat de către unitățile de reparații din Republica Moldova.","lvl":1},{"k":"al","n":"9","id":"a9","t":"Dacă pentru unele părți componente ale vehiculului nu există prețuri practicate de către unitățile de reparații, valoarea de nou a acestora se stabilește în baza prețurilor din cataloagele pieselor de schimb sau, în lipsa acestora, prin analogie cu prețurile părților componente ale unor vehicule similare.","lvl":1},{"k":"al","n":"10","id":"a10","t":"În procesul evaluării pagubei, atunci când este necesară înlocuirea părților componente și a pieselor avariate, în cazul plătirii despăgubirii de asigurare prin virament în contul bancar al unității de reparații, cuantumul despăgubirii de asigurare urmează a fi stabilit de către asigurătorul RCA, ținând cont de următoarele:","lvl":1},{"k":"lit","n":"a","id":"a10.la","t":"pentru vehiculele cu o vechime de exploatare de până la 3 ani, calculată de la data primei înmatriculări sau de la anul fabricației vehiculului, dacă data primei înmatriculări nu poate fi probată, și un parcurs de până la 100000 km, costul reparației vehiculului se stabilește în baza documentelor emise de către unitatea de reparații acceptată de părți sau de către cea indicată în certificatul de garanție valabil. În acest caz, la reparația vehiculului se vor utiliza părți componente și piese originale noi;","lvl":2},{"k":"note","t":"[Art.25 al.(10), lit.a) modificată prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"lit","n":"b","id":"a10.lb","t":"pentru vehiculele cu o vechime de exploatare de peste 3 ani, calculată de la data primei înmatriculări sau de la anul fabricației vehiculului, dacă data primei înmatriculări nu poate fi probată, și/sau un parcurs mai mare de 100000 km, costul reparației vehiculului se stabilește în baza documentelor emise de către unitatea de reparații acceptată de părți. În acest caz, la reparația vehiculului se vor utiliza părți componente și piese noi fabricate în bază de licență (piese after market) sau originale foste în folosință care corespund cerințelor tehnice și de securitate rutieră și sunt disponibile pe piața autohtonă. În cazul în care părțile componente și piesele noi fabricate în bază de licență sau cele originale foste în folosință nu sunt disponibile pe piața autohtonă, paguba real suportată pentru vehicule se va determina conform prețului părților componente și pieselor originale noi. În cazul în care părțile nu ajung la un acord cu privire la unitatea de reparație, despăgubirea de asigurare se va determina conform alin. (12)–(14).","lvl":2,"r":[[1033,1048,{"al":"12","al2":"14","art":"25"}]]},{"k":"note","t":"[Art.25 al.(10), lit.b) modificată prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n2","lvl":0},{"k":"al","n":"11","id":"a11","t":"În scopul prevăzut la alin. (10), la calcularea vechimii vehiculului se ia în considerare numărul întreg de ani calculat de la data de 1 ianuarie a anului primei înmatriculări a vehiculului, dacă data primei înmatriculări nu poate fi probată, sau a anului fabricației vehiculului și până la data survenirii cazului asigurat.","lvl":1,"r":[[22,32,{"al":"10","art":"25"}]]},{"k":"note","t":"[Art.25 al.(11) în redacția LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n3","lvl":0},{"k":"al","n":"12","id":"a12","t":"Asigurătorii RCA vor determina costul reparației vehiculelor, al materialelor, al părților componente și al pieselor înlocuitoare exclusiv, cu aplicarea sistemelor informaționale automatizate de evaluare în domeniul auto, care corespund cerințelor stabilite în actele normative ale Comisiei Naționale a Pieței Financiare.","lvl":1},{"k":"al","n":"13","id":"a13","t":"În cazul dezacordului persoanei păgubite privind cuantumul despăgubirii de asigurare, stabilit conform alin.(10) și (12), cu excepția cazului în care reparația a fost deja efectuată de către unitatea de reparații, costul reparației vehiculelor, al materialelor, al părților componente și al pieselor înlocuitoare se va determina de către asigurătorul RCA, ținând cont de sistemele informaționale automatizate de evaluare în domeniul auto ce corespund cerințelor stabilite în actele normative ale Comisiei Naționale a Pieței Financiare. Valoarea tarifului orei de manoperă este stabilită prin actul normativ al Comisiei Naționale a Pieței Financiare, în condițiile aplicabile Republicii Moldova. La determinarea valorii de reparație, conform prezentului alineat, nu se vor aplica cheltuielile de transport, taxele vamale și taxa pe valoare adăugată.","lvl":1,"r":[[103,112,{"al":"10","art":"25"}],[116,120,{"al":"12","art":"25"}]]},{"k":"al","n":"14","id":"a14","t":"Actele de evaluare a despăgubirii de asigurare, întocmite fără respectarea prevederilor prezentului articol, nu pot servi drept temei pentru plătirea despăgubirii de asigurare.","lvl":1},{"k":"al","n":"15","id":"a15","t":"Orice expertiză judiciară sau extrajudiciară, care are drept scop stabilirea despăgubirii de asigurare, trebuie efectuată, în mod obligatoriu, în conformitate cu prevederile prezentei legi.","lvl":1}]},{"id":"26","num":"26","title":"Stabilirea indemnizațiilor în cazul vătămării corporale și/sau al decesului","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazul vătămării corporale, indemnizația de asigurare pentru pierderea veniturilor va include:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"diferența dintre salariul mediu lunar net al persoanei păgubite, stabilit conform legislației privind modul de calcul al salariului mediu, și indemnizația primită din fondurile bugetului asigurărilor sociale de stat, pentru perioada incapacității temporare de muncă, probată cu documente justificative de la instituțiile competente – pentru persoanele salariate;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"venitul mediu lunar net declarat instituțiilor competente și probat cu documente justificative, pentru ultimele 12 luni, din activități desfășurate de către persoana păgubită, pentru perioada incapacității temporare de muncă, dar care nu va fi mai mic decât suma coșului minim de consum – pentru persoanele care nu au calitatea de salariat;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"o indemnizație egală cu suma coșului minim de consum, pentru perioada incapacității temporare de muncă, determinată conform declarațiilor prezentate instituțiilor competente și probată cu documente justificative – pentru persoanele păgubite care, la momentul survenirii cazului asigurat, nu întrunesc niciuna din exigențele stabilite la lit. a) și b).","lvl":2,"r":[[337,344,{"lit":"a","art":"26","al":"1"}],[348,350,{"lit":"b","art":"26","al":"1"}]]},{"k":"al","n":"2","id":"a2","t":"În cazul vătămărilor corporale se compensează și eventualele cheltuieli generate de accident, inclusiv cheltuielile de transport ale persoanei accidentate, de tratament, protezare, spitalizare, recuperare, îngrijire, alimentație specială conform prescripțiilor medicale, probate cu documente justificative, care nu sunt suportate din fondurile de asigurări medicale obligatorii, conform legislației. Cheltuielile menționate se stabilesc în baza prețurilor practicate de către instituțiile din Republica Moldova, conform documentelor eliberate de acestea sau în cazurile în care niciuna dintre instituțiile respective nu practică serviciile nominalizate, conform documentelor justificative eliberate de către instituțiile din străinătate.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul stabilirii dizabilității ca urmare a vătămărilor corporale, indemnizația de asigurare va include diferența dintre venitul mediu lunar net, determinat în conformitate cu alin. (1), și pensia de dizabilitate pe perioada dizabilității, în limitele prevederilor prezentei legi.","lvl":1,"r":[[178,187,{"al":"1","art":"26"}]]},{"k":"al","n":"4","id":"a4","t":"În caz de deces al persoanei păgubite, indemnizația de asigurare se stabilește prin acordul dintre persoana îndreptățită și asigurătorul RCA și include:","lvl":1},{"k":"note","t":"[Art.26 al.(4) partea introductivă modificată prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"lit","n":"a","id":"a4.la","t":"venitul mediu lunar net, determinat în conformitate cu alin. (1), minus indemnizațiile primite din fondurile bugetului asigurărilor sociale de stat pentru persoanele care s-au aflat la întreținerea defunctului sau care, la data decesului acestuia, aveau dreptul la întreținere în condițiile art. 2031 alin. (1) și (2) din Codul civil nr. 1107/2002;","lvl":2,"r":[[55,64,{"al":"1","art":"26"}],[291,310,{"art":"2031","al":"1","a":"cod:civil"}],[314,317,{"art":"2031","al":"2","a":"cod:civil"}],[322,347,{"a":"cod:civil","whole":true}]]},{"k":"note","t":"[Art.26 al.(4), lit.a) modificată prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n2","lvl":0},{"k":"lit","n":"b","id":"a4.lb","t":"cheltuielile de înmormântare – în cuantum de 4 salarii medii lunare pe economie, stabilite la data survenirii accidentului de vehicul.","lvl":2},{"k":"al","n":"5","id":"a5","t":"În cazul vătămărilor corporale sau al decesului cauzat de accidentul de vehicul, persoana păgubită, după caz, persoana îndreptățită poate solicita prejudiciu moral în limita prevăzută de prezenta lege.","lvl":1},{"k":"note","t":"[Art.26 al.(5) modificat prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n3","lvl":0}]},{"id":"27","num":"27","title":"Stabilirea despăgubirilor de asigurare în cazul vătămării sau pieirii animalelor","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Cuantumul despăgubirii de asigurare pentru vătămarea sau pieirea animalelor într-un accident de vehicul se stabilește în baza prețului animalelor de pe piața locală la data producerii accidentului. Cheltuielile de tratament al animalelor vor fi rambursate de către asigurătorul RCA în baza documentelor justificative prezentate de proprietarul lor.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Persoana păgubită va prezenta adeverința de la autoritatea competentă, care confirmă dreptul de proprietate asupra animalelor vătămate sau pierite.","lvl":1},{"k":"al","n":"3","id":"a3","t":"La calcularea despăgubirii de asigurare, în cazul animalelor vătămate care trebuie sacrificate și a căror carne poate fi valorificată, se ia în considerare costul cărnii valorificate.","lvl":1}]},{"id":"28","num":"28","title":"Stabilirea despăgubirilor de asigurare în caz de avariere sau distrugere de alte bunuri","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Despăgubirile de asigurare pentru avarierea sau distrugerea de bunuri cauzate de accidentul de vehicul, altele decât cele prevăzute la art. 25 și 27, se stabilesc în funcție de:","lvl":1,"r":[[135,142,{"art":"25"}],[146,148,{"art":"27"}]]},{"k":"lit","n":"a","id":"a1.la","t":"avariere – costul reparației, în limitele de răspundere prevăzute la art. 13 alin. (1) lit. a);","lvl":2,"r":[[69,94,{"art":"13","al":"1","lit":"a"}]]},{"k":"lit","n":"b","id":"a1.lb","t":"dauna totală – valoarea de piață minus costul materialelor rămase.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Documentele tehnice (costurile de reparație și alte cheltuieli), prezentate de către persoana păgubită, se iau în considerare la stabilirea despăgubirii de asigurare după verificarea acestora de către asigurătorul RCA.","lvl":1}]},{"id":"29","num":"29","title":"Plata despăgubirilor de asigurare","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurătorul RCA este obligat să plătească despăgubirile de asigurare în termen de cel mult 10 zile lucrătoare de la data emiterii deciziei cu privire la soluționarea cererii de despăgubire și să accepte cererea persoanei păgubite privind modalitatea de plată a despăgubirii de asigurare, care poate fi:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"în numerar;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"prin virament în cont bancar;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"prin virament în contul bancar al unității de reparații care a efectuat sau va efectua reparația.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Cererea privind obiecțiile referitoare la cuantumul despăgubirii de asigurare este înaintată asigurătorului RCA în termen de 5 zile lucrătoare de la finalizarea dosarului de daune, urmând ca, în termen de 5 zile lucrătoare de la data înștiințării, asigurătorul RCA să soluționeze cererea respectivă.","lvl":1},{"k":"note","t":"[Art.29 al.(2) modificat prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0},{"k":"al","n":"3","id":"a3","t":"Dacă persoana păgubită nu este de acord cu decizia asigurătorului RCA privind cuantumul despăgubirii de asigurare, asigurătorul plătește totuși despăgubirea de asigurare în cuantumul stabilit și persoana păgubită are dreptul să conteste decizia asigurătorului RCA în instanța de judecată.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Despăgubirea de asigurare nu poate fi urmărită de către creditorii asiguratului sau ai persoanei păgubite.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Despăgubirea de asigurare se plătește de către asigurătorul RCA nemijlocit persoanei fizice sau juridice păgubite, dacă aceasta nu a fost despăgubită de către persoana asigurată, sau unității de reparații, dacă în acordul dintre persoana păgubită și asigurător nu este stabilit altfel.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Despăgubirea de asigurare se plătește asiguraților, total sau parțial, dacă acestea probează că au despăgubit persoanele păgubite în conformitate cu prevederile prezentei legi și că despăgubirea de asigurare nu urmează a fi recuperată conform art. 30.","lvl":1,"r":[[243,250,{"art":"30"}]]},{"k":"al","n":"7","id":"a7","t":"În cazul în care în drepturile persoanei păgubite s-a subrogat asigurătorul asigurării facultative, oricare diferență de despăgubire dintre asigurarea facultativă și asigurarea obligatorie RCA rămâne pe contul asigurării facultative, fără a fi recuperată de la asigurat, dacă despăgubirea de asigurare plătită din asigurarea facultativă nu depășește limita maximă a despăgubirii care poate fi acordată de către asigurătorul RCA pentru paguba produsă în același accident de vehicul, în conformitate cu legislația.","lvl":1}]},{"id":"30","num":"30","title":"Regresul asigurătorului RCA","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurătorul RCA care a plătit despăgubirea de asigurare are dreptul sa înainteze acțiune de regres în limitele acestei sume în cazul în care:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"nu a fost îndeplinită obligația de încheiere a unui contract de asigurare obligatorie RCA, în condițiile art. 8 alin. (3) și (4);","lvl":2,"r":[[105,121,{"art":"8","al":"3"}],[125,128,{"art":"8","al":"4"}]]},{"k":"lit","n":"b","id":"a1.lb","t":"vehiculul nu dispune de raport de inspecție tehnică periodică, valabil la momentul producerii accidentului;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"accidentul a fost produs cu intenție sau a fost produs în timpul comiterii intenționate a unei infracțiuni;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"accidentul a fost produs în timpul când făptuitorul infracțiunii săvârșite a încercat să evadeze de la forțele de ordine;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"vehiculul era condus cu încălcarea regulilor privind dreptul de conducere, constatată în condițiile Codului contravențional;","lvl":2,"r":[[100,123,{"a":"cod:contraventional","whole":true}]]},{"k":"lit","n":"f","id":"a1.lf","t":"conducătorul vehiculului a părăsit locul accidentului contrar prevederilor legale care reglementează circulația rutieră pe drumurile naționale și cele locale;","lvl":2},{"k":"lit","n":"g","id":"a1.lg","t":"conducătorul vehiculului era în stare de ebrietate survenită în urma consumului de alcool, droguri și/sau alte substanțe cu efecte similare ori conducătorul vehiculului a refuzat testarea alcoolscopică ori narcologică sau după caz, examinarea medicală cu recoltarea probelor biologice, cu excepția celor prevăzute la art. 21 alin. (7).","lvl":2,"r":[[317,334,{"art":"21","al":"7"}]]},{"k":"al","n":"2","id":"a2","t":"Asigurătorul RCA are dreptul să solicite persoanei culpabile de producerea accidentului de vehicul și/sau persoanei păgubite recuperarea cheltuielilor suportate în legătură cu instrumentarea dosarului de daune deschis în temeiul cererii de despăgubire neîntemeiată.","lvl":1}]},{"id":"31","num":"31","title":"Decontarea directă dintre asigurătorii RCA","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurătorii RCA pot oferi, în mod voluntar, decontare directă asiguraților. Decontarea directă dintre asigurătorii RCA este aplicabilă la îndeplinirea cumulativă a următoarelor condiții:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"accidentele de vehicul se produc pe teritoriul Republicii Moldova;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"vehiculele implicate în accident sunt înmatriculate în Republica Moldova;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"daunele sunt produse exclusiv vehiculelor;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"ambele vehicule implicate în accident dispun de asigurare obligatorie RCA valabilă la data cazului asigurat;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"pagubele exclud vătămările corporale, decesul și prejudiciile morale;","lvl":2},{"k":"lit","n":"f","id":"a1.lf","t":"asigurătorii RCA dispun de unul dintre sistemele informaționale automatizate de evaluare în domeniul auto care corespund cerințelor stabilite în actele normative ale Comisiei Naționale a Pieței Financiare.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Procedura de decontare directă se stabilește prin actele normative ale Comisiei Naționale a Pieței Financiare.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Decontarea directă nu aduce atingere dreptului persoanei păgubite în accidentul de vehicul, al cărui proprietar și/sau utilizator a îndeplinit obligația de asigurare obligatorie RCA, de a institui proceduri pentru recuperarea despăgubirii împotriva asigurătorului RCA al persoanei culpabile de producerea accidentului de vehicul.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În cazul în care persoana păgubită se adresează asigurătorului RCA cu care are încheiat contract de asigurare obligatorie RCA în scopul recuperării despăgubirii, constatarea circumstanțelor accidentului de vehicul, soluțiile tehnice adoptate, evaluarea și stabilirea despăgubirilor de asigurare vor fi opozabile asigurătorului RCA al persoanei culpabile care deține contract de asigurare obligatorie RCA, în limitele prevederilor prezentei legi, dacă asigurătorul RCA al persoanei păgubite a respectat procedura de invitare a asigurătorului RCA al persoanei culpabile prevăzută la alin. (5).","lvl":1,"r":[[581,590,{"al":"5","art":"31"}]]},{"k":"al","n":"5","id":"a5","t":"Asigurătorul RCA al persoanei păgubite este obligat să invite la procesul de constatare a pagubei persoana culpabilă și asigurătorul RCA al acesteia, probând invitația printr-un document justificativ. Neprezentarea asigurătorului RCA al persoanei culpabile la data și locul stabilit nu împiedică asigurătorul RCA al persoanei păgubite să constate și să evalueze pagubele ce vor fi opozabile asigurătorului RCA absent de la procesul de constatare, în limitele prevederilor prezentei legi.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Pentru respectarea prevederilor alin. (5), asigurătorul RCA al persoanei păgubite recuperează de la asigurătorul RCA al persoanei culpabile despăgubirea de asigurare plătită persoanei păgubite, în limitele stabilite de prezenta lege pentru unul și același accident de vehicul.","lvl":1,"r":[[32,41,{"al":"5","art":"31"}]]}]},{"id":"32","num":"32","title":"Organizarea BNAA-ului","node":"n10","blocks":[{"k":"al","n":"1","id":"a1","t":"BNAA este o asociație profesională, necomercială, independentă și autonomă, bazată pe principiul apartenenței obligatorii a tuturor societăților de asigurare, care, în condițiile legii, au dreptul de a desfășura în Republica Moldova activitate de asigurare obligatorie RCA.","lvl":1},{"k":"al","n":"2","id":"a2","t":"BNAA deține competențe de reprezentare și îndeplinește prerogativele și atribuțiile de birou național în Consiliul Birourilor, precum și calitatea de membru al acestuia.","lvl":1},{"k":"al","n":"3","id":"a3","t":"BNAA își desfășoară activitatea în baza propriului statut, a prezentei legi, a reglementărilor Consiliului Birourilor, a actelor normative ale Băncii Naționale a Moldovei și a altor acte normative.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Statutul BNAA-ului și modificările acestuia se aprobă de către Adunarea generală a membrilor BNAA și se înregistrează în modul stabilit de legislație, cu avizul prealabil al Băncii Naționale a Moldovei.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Activitatea, patrimoniul și atribuțiile BNAA-ului, Fondul de protecție a victimelor străzii și Fondul de compensare sunt supuse supravegherii de către Banca Națională a Moldovei în conformitate cu legislația.","lvl":1}]},{"id":"33","num":"33","title":"Atribuțiile BNAA-ului","node":"n10","blocks":[{"k":"al","n":"1","id":"a1","t":"BNAA îndeplinește următoarele atribuții de bază:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"monitorizează activitatea membrilor săi privind exercitarea drepturilor și respectarea obligațiilor aferente asigurării obligatorii RCA externe;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"gestionează și utilizează mijloacele financiare ale Fondului de protecție a victimelor străzii și cele ale Fondului de compensare, constituite în temeiul prezentei legi;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"instrumentează și soluționează direct sau prin intermediul corespondenților sau al agenților săi cererile de despăgubire pentru pagubele produse pe teritoriul Republicii Moldova de accidentele de vehicule înmatriculate în statele membre ale Sistemului Internațional de Asigurări „Carte Verde”, în condițiile și limitele de răspundere prevăzute de prezenta lege, cu respectarea procedurilor stabilite în Regulamentul general al Consiliului Birourilor;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"îndeplinește funcțiile care îi sunt atribuite ca membru al Consiliului Birourilor, angajamentele care decurg din acordurile cu birourile naționale din statele terțe și alte funcții, conform cerințelor actelor normative care reglementează Sistemul Internațional de Asigurări „Carte Verde”;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"reprezintă Republica Moldova în relațiile externe din cadrul Consiliului Birourilor;","lvl":2},{"k":"lit","n":"f","id":"a1.lf","t":"reprezintă direct sau prin intermediarii desemnați interesele birourilor naționale din statele membre ale Sistemului Internațional de Asigurări „Carte Verde”, precum și ale societăților de asigurare, membre ale birourilor naționale, în fața autorităților și organizațiilor naționale, inclusiv în instanțele de judecată din Republica Moldova;","lvl":2},{"k":"lit","n":"g","id":"a1.lg","t":"asigură apartenența Republicii Moldova la Sistemul Internațional de Asigurări „Carte Verde” și îndeplinirea obligațiilor general recunoscute față de organizațiile autorizate din țările membre ale acestui sistem;","lvl":2},{"k":"lit","n":"h","id":"a1.lh","t":"utilizează în comun cu Banca Națională a Moldovei Sistemul informațional automatizat de stat în domeniul asigurărilor obligatorii RCA;","lvl":2},{"k":"lit","n":"i","id":"a1.li","t":"stabilește și aplică sancțiuni, cu excepția suspendării sau încetării calității de membru, pentru nerespectarea prevederilor statutului și/sau a prevederilor Regulamentului general al Consiliului Birourilor;","lvl":2},{"k":"lit","n":"j","id":"a1.lj","t":"aplică membrilor săi penalități în mărime de 12% anual, calculate din suma datorată de membru, începând cu data chemării BNAA-ului în garanție și până la data achitării efective de către membru a sumei datorate. Penalitățile aplicate se fac venit la bugetul BNAA-ului;","lvl":2},{"k":"lit","n":"k","id":"a1.lk","t":"tipărește și eliberează asigurătorilor RCA licențiați să desfășoare activitate de asigurare obligatorie RCA externă formulare de certificate de asigurare „Carte Verde” în termen de 30 de zile de la data efectuării plății de către asigurătorul RCA a costului acestor formulare sau autorizează membrii săi să le tipărească;","lvl":2},{"k":"lit","n":"l","id":"a1.ll","t":"încheie acorduri de colaborare privind schimbul de informații cu autoritățile publice și cu alte instituții în vederea îndeplinirii prevederilor legale;","lvl":2},{"k":"lit","n":"m","id":"a1.lm","t":"exercită alte atribuții stabilite de prezenta lege și de statutul său.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Atribuția BNAA-ului menționată la alin. (l) lit. k) decade din data de la care asigurătorii RCA licențiați să desfășoare activitate de asigurare obligatorie RCA externă sunt autorizați să emită certificate de asigurare ,,Carte Verde” în format electronic, conform modelului aprobat de către Consiliul Birourilor. Certificatele de asigurare ,,Carte Verde”, eliberate în condițiile alin. (l) lit. k), sunt valabile până la expirarea perioadei de acoperire a asigurării.","lvl":1,"r":[[44,51,{"lit":"k","art":"33","al":"2"}],[390,397,{"lit":"k","art":"33","al":"2"}]]},{"k":"al","n":"3","id":"a3","t":"În vederea realizării supravegherii, BNAA:","lvl":1},{"k":"lit","n":"a","id":"a3.la","t":"informează sistematic Banca Națională a Moldovei cu privire la neonorarea obligațiilor de către membrii săi, la practicile frauduloase ale acestora, la sancțiunile aplicate membrilor, precum și la reclamațiile și sesizările venite din partea altor birouri naționale;","lvl":2},{"k":"lit","n":"b","id":"a3.lb","t":"elaborează și prezintă Băncii Naționale a Moldovei, în termen de 4 luni de la sfârșitul perioadei de gestiune, raportul anual de activitate și raportul auditorului emis de către o entitate de audit care face parte dintr-o rețea internațională înregistrată în Registrul public al entităților de audit, în modul prevăzut de legislația din domeniul auditului, cu publicarea acestora pe pagina web oficială a sa.","lvl":2}]},{"id":"34","num":"34","title":"Conducerea BNAA-ului","node":"n10","blocks":[{"k":"al","n":"1","id":"a1","t":"Organele de conducere ale BNAA-ului sunt:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"Adunarea generală a membrilor;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"Consiliul de supraveghere, condus de către un președinte;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"directorul executiv.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Structura organelor de conducere ale BNAA-ului, competența acestora, procedura de convocare și desfășurare a ședințelor și de adoptare a deciziilor se stabilesc în statutul BNAA-ului.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Adunarea generală a membrilor are următoarele atribuții exclusive:","lvl":1},{"k":"lit","n":"a","id":"a3.la","t":"aprobă statutul și modificările la statut;","lvl":2},{"k":"lit","n":"b","id":"a3.lb","t":"alege și revocă directorul executiv, membrii Consiliului de supraveghere și stabilește componența numerică a acestuia și durata mandatului;","lvl":2},{"k":"lit","n":"c","id":"a3.lc","t":"confirmă entitatea de audit și stabilește onorariul de audit;","lvl":2},{"k":"lit","n":"d","id":"a3.ld","t":"aprobă și modifică devizul anual de venituri și cheltuieli, raportul anual și situațiile financiare ale BNAA-ului;","lvl":2},{"k":"lit","n":"e","id":"a3.le","t":"decide cu privire la reorganizarea sau lichidarea benevolă a BNAA-ului;","lvl":2},{"k":"lit","n":"f","id":"a3.lf","t":"decide cu privire la alte chestiuni care intră în sfera de competență a sa stabilite prin statut.","lvl":2},{"k":"al","n":"4","id":"a4","t":"Adunarea generală a membrilor adoptă hotărâri cu votul majorității simple a membrilor BNAA-ului prezenți la adunare. Adunarea generală a membrilor este deliberativă dacă la adunare s-au înregistrat și participă cel puțin 2/3 din membrii cu drept de vot.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Prin derogare de la prevederile alin. (4), hotărârile Adunării generale ale membrilor ce vizează aspecte ale asigurării obligatorii RCA externe, precum și cele ce vizează competențele stabilite la alin. (3) lit. a), b) și d) sunt adoptate în exclusivitate cu votul majorității simple a asigurătorilor RCA licențiați să desfășoare activitate de asigurare obligatorie RCA externă, prezenți la adunare.","lvl":1,"r":[[32,41,{"al":"4","art":"34"}],[197,214,{"al":"3","lit":"a","art":"34"}],[216,218,{"al":"3","lit":"b","art":"34"}],[222,224,{"al":"3","lit":"d","art":"34"}]]},{"k":"al","n":"6","id":"a6","t":"Consiliul de supraveghere reprezintă interesele membrilor BNAA-ului în perioada dintre adunările generale ale membrilor și în limitele atribuțiilor sale și exercită conducerea generală și controlul asupra activității BNAA-ului. Consiliul de supraveghere este subordonat Adunării generale a membrilor și are următoarele atribuții:","lvl":1},{"k":"lit","n":"a","id":"a6.la","t":"decide convocarea adunărilor generale, după caz;","lvl":2},{"k":"lit","n":"b","id":"a6.lb","t":"elaborează și stabilește strategia activității BNAA-ului;","lvl":2},{"k":"lit","n":"c","id":"a6.lc","t":"examinează, aprobă și prezintă Adunării generale a membrilor raportul anual de activitate al BNAA-ului;","lvl":2},{"k":"lit","n":"d","id":"a6.ld","t":"aprobă regulamentele interne de funcționare, organigrama și statul de personal din subordinea directorului executiv al BNAA-ului;","lvl":2},{"k":"lit","n":"e","id":"a6.le","t":"supraveghează colaborarea BNAA-ului cu autoritățile administrației publice centrale și locale;","lvl":2},{"k":"lit","n":"f","id":"a6.lf","t":"decide cu privire la alte aspecte care intră în sfera de competență a sa, astfel cum este prevăzut în statutul BNAA-ului, precum și chestiunile adoptate de către Adunarea generală a membrilor.","lvl":2},{"k":"al","n":"7","id":"a7","t":"Procedura de alegere a membrilor Consiliului de supraveghere și de luare a deciziilor se stabilește în statutul BNAA-ului și în regulamentul de funcționare al acestuia.","lvl":1},{"k":"al","n":"8","id":"a8","t":"Membrii Consiliului de supraveghere sunt delegați de către membrii BNAA-ului și nu au dreptul de a delega sau de a transmite atribuțiile lor către alte persoane.","lvl":1},{"k":"al","n":"9","id":"a9","t":"Directorul executiv reprezintă BNAA în relațiile cu Consiliul Birourilor și cu birourile naționale din statele membre ale Sistemului Internațional de Asigurări „Carte Verde”, având următoarele atribuții exclusive:","lvl":1},{"k":"lit","n":"a","id":"a9.la","t":"organizează activitatea BNAA-ului și ia deciziile necesare pentru asigurarea îndeplinirii activităților acestuia;","lvl":2},{"k":"lit","n":"b","id":"a9.lb","t":"gestionează fondurile existente în cadrul BNAA-ului;","lvl":2},{"k":"lit","n":"c","id":"a9.lc","t":"organizează și administrează activitatea economico-operațională a BNAA-ului;","lvl":2},{"k":"lit","n":"d","id":"a9.ld","t":"emite avize și propuneri Consiliului de supraveghere și Adunării generale a membrilor cu privire la unele chestiuni care intră în sfera de competență a acestuia;","lvl":2},{"k":"lit","n":"e","id":"a9.le","t":"notifică, în scris, Banca Națională a Moldovei cu privire la transmiterea datelor/informațiilor relevante aferente entității de audit confirmate de Adunarea generală a membrilor;","lvl":2},{"k":"lit","n":"f","id":"a9.lf","t":"monitorizează în permanență, cu notificarea în formă scrisă a Consiliului de supraveghere, onorarea de către membrii titulari a obligațiilor financiare în cadrul Sistemului Internațional de Asigurări „Carte Verde”;","lvl":2},{"k":"lit","n":"g","id":"a9.lg","t":"decide alte chestiuni care intră în sfera de competență a directorului executiv, astfel cum este prevăzut în statut.","lvl":2},{"k":"al","n":"10","id":"a10","t":"Eliberarea formularelor certificatelor de asigurare „Carte Verde” asigurătorilor RCA licențiați să desfășoare activitate de asigurare obligatorie RCA externă, în cazul în care aceștia nu sunt autorizați să le tipărească, ține de competența exclusivă a directorului executiv. Competența în cauză este valabilă până la data și în situația specificate la art. 33 alin. (2).","lvl":1,"r":[[352,369,{"art":"33","al":"2"}]]},{"k":"al","n":"11","id":"a11","t":"Numirea în funcție a directorului executiv al BNAA-ului se aprobă în prealabil de către Banca Națională a Moldovei. Directorul executiv trebuie să corespundă cerințelor stabilite pentru persoanele cu funcție de conducere de legislația privind activitatea de asigurare sau de reasigurare și de actele normative ale Băncii Naționale a Moldovei și nu are dreptul să transmită responsabilitățile sale altor persoane.","lvl":1},{"k":"al","n":"12","id":"a12","t":"Dacă directorul executiv nu își poate exercita atribuțiile din cauza unor circumstanțe obiective, probate prin documente justificative, atribuțiile acestuia sunt exercitate temporar de către o persoană desemnată în acest sens de către Adunarea generală a membrilor și avizată în prealabil de către Banca Națională a Moldovei, care trebuie să corespundă cerințelor stabilite pentru persoanele cu funcție de conducere de legislația privind activitatea de asigurare sau de reasigurare și de actele normative ale Băncii Naționale a Moldovei.","lvl":1},{"k":"al","n":"13","id":"a13","t":"Banca Națională a Moldovei are dreptul să retragă avizul și/sau să recomande Adunării generale a membrilor înlocuirea persoanei care deține funcția de director executiv dacă titularul funcției:","lvl":1},{"k":"lit","n":"a","id":"a13.la","t":"nu corespunde cerințelor prevăzute în actele normative ale Băncii Naționale a Moldovei;","lvl":2},{"k":"lit","n":"b","id":"a13.lb","t":"a fost desemnat în baza unor informații neveridice sau incomplete;","lvl":2},{"k":"lit","n":"c","id":"a13.lc","t":"a comis încălcări ale cadrului normativ intern și/sau internațional aferent activității BNAA-ului, care au dus la producerea riscurilor semnificative și au afectat soliditatea financiară a acestuia.","lvl":2},{"k":"al","n":"14","id":"a14","t":"Adunarea generală a membrilor notifică Banca Națională a Moldovei despre modificarea/încetarea raporturilor de muncă cu directorul executiv, cu expunerea motivelor aferente, în termen de 5 zile de la data încetării exercitării atribuțiilor de către ultimul.","lvl":1},{"k":"al","n":"15","id":"a15","t":"În cazul prevăzut la alin. (14), Adunarea generală a membrilor desemnează un nou titular al funcției de director executiv cât mai curând posibil, dar nu mai târziu de o lună de la data încetării exercitării atribuțiilor ex-directorului.","lvl":1,"r":[[21,31,{"al":"14","art":"34"}]]},{"k":"al","n":"16","id":"a16","t":"Alte atribuții ale organelor de conducere ale BNAA-ului sunt reglementate prin statutul BNAA-ului și prin alte acte interne, aprobate conform legislației.","lvl":1}]},{"id":"35","num":"35","title":"Calitatea de membru al BNAA-ului","node":"n10","blocks":[{"k":"al","n":"1","id":"a1","t":"Calitatea de membru al BNAA-ului se obține de către asigurătorul RCA din momentul în care este licențiat să desfășoare activitate de asigurarea obligatorie RCA internă sau pentru asigurarea obligatorie RCA internă și externă.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Suspendarea sau retragerea licenței pentru desfășurarea activității de asigurare obligatorie RCA atrage după sine suspendarea sau retragerea calității de membru al BNAA-ului.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Banca Națională a Moldovei informează BNAA-ul și Comisia Națională a Pieței Financiare despre eliberarea, suspendarea sau retragerea licenței pentru desfășurarea activității de asigurare obligatorie RCA internă sau pentru asigurarea obligatorie RCA internă și externă în termen de 3 zile lucrătoare de la data adoptării hotărârii.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Asigurătorul care deține calitatea de membru al BNAA-ului are drept de vot deliberativ în Adunarea generală a membrilor.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Membrii BNAA-ului, care sunt licențiați să desfășoare activitate de asigurare obligatorie RCA internă și externă, poartă răspundere comună și solidară pentru obligațiile din trecut, prezente și viitoare ale BNAA-ului, asumate în cadrul Sistemului Internațional de Asigurări „Carte Verde”.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Membrii BNAA-ului, care sunt licențiați să desfășoare activitate de asigurare obligatorie RCA internă și externă, își vor desfășura activitatea în conformitate cu regulile stabilite de regulamentele interne ale Consiliului Birourilor și în scopul menținerii BNAA-ului în cadrul Sistemului Internațional de Asigurări „Carte Verde”.","lvl":1},{"k":"al","n":"7","id":"a7","t":"Temei pentru suspendarea sau retragerea licenței pentru desfășurarea activității de asigurare obligatorie RCA externă de către Banca Națională a Moldovei poate servi decizia organului de conducere al BNAA-ului privind aplicarea sancțiunilor în cazul în care:","lvl":1},{"k":"lit","n":"a","id":"a7.la","t":"BNAA primește 3 sau mai multe cereri justificate de chemare în garanție într-un interval de 3 luni pentru unul și același membru;","lvl":2},{"k":"lit","n":"b","id":"a7.lb","t":"asigurătorul datorează plăți și cotizații ce rezultă din calitatea lui de membru al BNAA-ului, inclusiv pentru plata primei de reasigurare, și nu își îndeplinește obligațiile financiare față de BNAA în termen de până la 90 de zile de la primirea unei notificări corespunzătoare din partea BNAA-ului.","lvl":2}]},{"id":"36","num":"36","title":"Patrimoniul BNAA-ului","node":"n10","blocks":[{"k":"al","n":"1","id":"a1","t":"Patrimoniul BNAA-ului se constituie din:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"cotizațiile de înscriere și cotizațiile anuale de membru, stabilite în bugetul BNAA-ului;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"contribuțiile lunare în Fondul de protecție a victimelor străzii și dobânzile aferente activelor în acest fond;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"contribuțiile lunare în Fondul de compensare și dobânzile aferente lor;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"venitul din activitatea de regularizare a daunelor;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"alte surse legale de venit.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Cotizația anuală de membru reprezintă partea asigurătorului RCA în veniturile BNAA-ului, planificate din astfel de cotizații, și se determină ca o cotă procentuală din veniturile planificate. Cota procentuală este egală cu cota procentuală a primelor brute de asigurări obligatorii RCA subscrise de către asigurători în volumul total al primelor brute de asigurări RCA subscrise de toți asigurătorii licențiați să emită polițe de asigurare RCA pentru perioada de gestiune curentă. Cotizația anuală de membru se determină pentru asigurarea obligatorie RCA internă și externă separat și se plătește trimestrial, până la data de 25 a lunii următoare trimestrului de gestiune.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Cotizația de înscriere reprezintă suma mijloacelor financiare pe care membrul potențial o plătește la BNAA. Mărimea cotizației de înscriere se stabilește în statutul BNAA-ului și nu poate depăși suma de 5000 de lei.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Cheltuielile aferente îndeplinirii prerogativelor și atribuțiilor BNAA-ului în Consiliul Birourilor vor fi acoperite de partea cotizației anuale de membru, stabilită pentru asigurătorii RCA licențiați să desfășoare activitate de asigurare obligatorie RCA externă.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Contribuțiile lunare în Fondul de protecție a victimelor străzii și în Fondul de compensare devin proprietate a BNAA-ului și nu se restituie în caz de anulare sau încetare a calității de membru al acestuia.","lvl":1}]},{"id":"37","num":"37","title":"Garanția financiară externă","node":"n10","blocks":[{"k":"al","n":"1","id":"a1","t":"Garanția financiară externă se constituie de către BNAA la recomandarea, în mărimea stabilită și în favoarea Consiliului Birourilor, pentru acoperirea pagubelor neplătite de către asigurătorii RCA, în baza contractelor de asigurare obligatorie RCA externă încheiate și care decurg din propriile retenții de risc.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Contribuția asigurătorului RCA la garanția financiară externă se calculează ca raport între mărimea garanției și numărul de asigurători RCA licențiați să desfășoare activitate de asigurare obligatorie RCA internă și externă.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Cota financiară a asigurătorului RCA la garanția financiară externă nu se admite ca un activ eligibil care acoperă rezervele lor tehnice, cerințele de capital minim și marja de solvabilitate, fiind un activ grevat cu sarcini.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În cazul obținerii de către asigurătorul RCA a licenței pentru desfășurarea activității de asigurare obligatorie RCA internă și externă în perioada în care este în vigoare cerința de menținere a garanției financiare externe, BNAA recalculează contribuțiile la garanția financiară externă și restituie, în termen de 30 de zile de la data adoptării deciziei Băncii Naționale a Moldovei privind eliberarea licenței, surplusul creat prin intrarea contribuției asigurătorului RCA nou licențiat asigurătorilor RCA care dețin licență la momentul recalculării.","lvl":1},{"k":"al","n":"5","id":"a5","t":"În cazul retragerii licenței asigurătorului RCA pentru desfășurarea activității de asigurare obligatorie RCA internă și externă în perioada în care este în vigoare cerința de menținere a garanției financiare externe, BNAA recalculează contribuțiile la garanția financiară externă, iar asigurătorii RCA care dețin licență la momentul recalculării sunt obligați să suplinească insuficiența în termen de 30 de zile de la data intrării în vigoare a deciziei Băncii Naționale a Moldovei privind retragerea licenței.","lvl":1},{"k":"al","n":"6","id":"a6","t":"În cazul prevăzut la alin. (5) din prezentul articol, contribuția asigurătorului RCA la garanția financiară externă și dobânda aferentă se transformă în contribuție suplimentară a acestuia la Fondul de compensare, cu respectarea prevederilor art. 40 alin. (2) lit. b).","lvl":1,"r":[[21,30,{"al":"5","art":"37"}],[242,267,{"art":"40","al":"2","lit":"b"}]]}]},{"id":"38","num":"38","title":"Competențele BNAA-ului în calitate de organism de plată a despăgubirilor de asigurare","node":"n11","blocks":[{"k":"al","n":"1","id":"a1","t":"Obiectivul de bază al BNAA este de a asigura protecția intereselor persoanelor păgubite în accidente de vehicule și de a promova stabilitatea și dezvoltarea asigurării obligatorii RCA.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Pentru îndeplinirea acestui obiectiv, BNAA garantează despăgubirea de asigurare persoanelor păgubite:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"pe teritoriul statelor membre ale Sistemului Internațional de Asigurări „Carte Verde”, pentru pagubele produse de accidente de vehicule înmatriculate în Republica Moldova, în cazul în care asiguratul deține un certificat de asigurare „Carte Verde”, eliberat în numele unui asigurător RCA membru al BNAA-ului;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"pe teritoriul Republicii Moldova, pentru pagubele produse de accidente de vehicule înmatriculate în statele membre ale Sistemului Internațional de Asigurări „Carte Verde”, ai căror proprietari și/sau utilizatori dețin certificat de asigurare „Carte Verde”, eliberat de un asigurător membru al biroului național din țara de reședință, în condițiile și în limitele stabilite de prezenta lege, cu recuperarea ulterioară a cheltuielilor suportate din contul asigurătorului RCA al persoanei culpabile;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"pe teritoriul Republicii Moldova, pentru pagubele produse persoanelor păgubite de accidentele de vehicule ai căror proprietari și/sau utilizatori nu au încheiat contracte de asigurare obligatorie RCA sau de vehicule și/sau conducători de vehicule neidentificați, de vehicule neînregistrate sau care nu au fost supuse înmatriculării pe teritoriul Republicii Moldova, precum și de vehicule obținute pe cale ilicită și neasigurate RCA.","lvl":2},{"k":"al","n":"3","id":"a3","t":"În calitate de organism de plată a despăgubirilor de asigurare, BNAA utilizează mijloacele financiare ale Fondului de protecție a victimelor străzii și ale Fondului de compensare în conformitate cu prevederile prezentei legi și ale actelor normative ale Băncii Naționale a Moldovei.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Nicio persoană de drept public sau privat care a despăgubit în orice fel persoanele păgubite sau a oferit acestora servicii în legătură cu pagubele suferite nu are dreptul să solicite de la BNAA recuperarea cheltuielilor efectuate.","lvl":1},{"k":"al","n":"5","id":"a5","t":"BNAA nu poate plăti despăgubiri de asigurare pentru pagubele produse de un singur accident, care să depășească limitele de răspundere ale asigurătorului RCA, prevăzute de legislație la momentul producerii accidentului în Republica Moldova sau de legislația celorlalte state pe al căror teritoriu s-a produs accidentul, din care va fi dedusă, după caz, franșiza prevăzută de lege.","lvl":1}]},{"id":"39","num":"39","title":"Fondul de protecție a victimelor străzii","node":"n11","blocks":[{"k":"al","n":"1","id":"a1","t":"Fondul de protecție a victimelor străzii se constituie în vederea protejării persoanelor păgubite prin accidente de vehicule ai căror proprietari și/sau utilizatori nu au încheiat contracte de asigurare obligatorie RCA, de vehicule și/sau conducători de vehicule neidentificați, de vehicule neînregistrate sau care nu au fost supuse înmatriculării pe teritoriul Republicii Moldova și/sau de vehicule obținute pe cale ilicită și neasigurate RCA.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Asigurătorii RCA licențiați să desfăşoare activitate de asigurare obligatorie RCA sunt obligați să contribuie la constituirea fondului prevăzut la alin. (1), proporțional volumului primelor de asigurare încasate pentru această clasă de asigurare, în conformitate cu actele normative ale Băncii Naționale a Moldovei. Cuantumul cotizațiilor asigurătorilor RCA la acest fond se stabilește prin actele normative ale Băncii Naționale a Moldovei.","lvl":1,"r":[[147,156,{"al":"1","art":"39"}]]},{"k":"al","n":"3","id":"a3","t":"Fondul de protecție a victimelor străzii este destinat plății despăgubirilor de asigurare în următoarele condiții:","lvl":1},{"k":"lit","n":"a","id":"a3.la","t":"dacă vehiculul și/sau conducătorul de vehicul au fost identificați, dar nu a îndeplinit obligația de a încheia un contract de asigurare obligatorie RCA și/sau vehiculele nu sunt înregistrate sau nu au fost supuse înmatriculării pe teritoriul Republicii Moldova, despăgubirea de asigurare se plătește pentru distrugerea de bunuri și vătămări corporale sau deces;","lvl":2},{"k":"lit","n":"b","id":"a3.lb","t":"dacă vehiculul și/sau conducătorul de vehicul au rămas neidentificați, indemnizația de asigurare se plătește exclusiv pentru vătămări corporale sau deces, iar în cazul în care un astfel de accident de vehicul a provocat deces sau vătămare corporală care a condus la stabilirea dizabilității, atunci se plătește o despăgubire de asigurare și pentru pagubele materiale aduse persoanei vătămate cu echivalentul în lei al sumei ce depășește 200 de euro, la cursul oficial de schimb al leului moldovenesc, comunicat de către Banca Națională a Moldovei la data producerii accidentului. Accidentul cauzat de un vehicul care a rămas neidentificat este accidentul în care vehiculul a intrat în coliziune directă cu partea păgubită sau cu bunurile deteriorate de acesta, după care vehiculul a părăsit locul accidentului;","lvl":2},{"k":"lit","n":"c","id":"a3.lc","t":"dacă vehiculul a fost obținut pe cale ilicită și nu are asigurare obligatorie RCA, indemnizația de asigurare se plătește pentru vătămări corporale sau deces, iar pentru pagubele materiale aduse persoanei cu echivalentul în lei al sumei ce depășește 100 de euro, la cursul oficial de schimb al leului moldovenesc, comunicat de către Banca Națională a Moldovei la data producerii accidentului;","lvl":2},{"k":"lit","n":"d","id":"a3.ld","t":"dacă accidentul are loc în perioada suspendării contractului de asigurare obligatorie RCA, despăgubirea de asigurare se plătește pentru distrugerea de bunuri și vătămări corporale sau deces, indiferent de persoana care l-a cauzat.","lvl":2},{"k":"al","n":"4","id":"a4","t":"Mijloacele financiare ale Fondului de protecție a victimelor străzii se gestionează și se utilizează de către BNAA potrivit actelor normative ale Băncii Naționale a Moldovei și actelor interne emise în acest sens. Cheltuielile de constituire, gestionare și utilizare a mijloacelor fondului menționat se vor acoperi din disponibilitățile acestuia.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Despăgubirile de asigurare plătite din Fondul de protecție a victimelor străzii nu vor depăși limitele de răspundere stabilite la art. 13.","lvl":1,"r":[[130,137,{"art":"13"}]]},{"k":"al","n":"6","id":"a6","t":"BNAA are obligația de a ține o evidență distinctă a contribuțiilor în Fondul de protecție a victimelor străzii și a cheltuielilor lui, de a păstra disponibilitățile acestuia în instrumente financiare purtătoare de dobândă la bănci, în instrumente ale pieței monetare sau în valori mobiliare de stat.","lvl":1},{"k":"al","n":"7","id":"a7","t":"În caz de deficit al Fondului de protecție a victimelor străzii, Banca Națională a Moldovei poate majora pe parcursul anului, pentru acoperirea obligațiilor fondului menționat, contribuția stabilită prin actele sale normative.","lvl":1},{"k":"al","n":"8","id":"a8","t":"În vederea recuperării sumelor cheltuite din Fondul de protecție a victimelor străzii, BNAA poate înainta, în limitele despăgubirii de asigurare plătite și ale cheltuielilor de instrumentare a dosarului de daune, acțiune de regres față de persoanele culpabile de producerea pagubelor întru-un accident.","lvl":1}]},{"id":"40","num":"40","title":"Fondul de compensare","node":"n11","blocks":[{"k":"al","n":"1","id":"a1","t":"BNAA gestionează și utilizează, în strictă conformitate cu Regulamentul general al Consiliului Birourilor, mijloacele financiare ale Fondului de compensare, instituit pentru a garanta:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"rambursarea către birourile naționale, asigurătorii sau corespondenții din străinătate a sumelor plătite de către aceștia cu titlu de despăgubire de asigurare pentru pagubele produse de către deținătorii de certificate de asigurare „Carte Verde”;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"recuperarea pagubelor produse de către deținătorii de certificate de asigurare „Carte Verde” false sau neautorizate;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"plata sumelor datorate către persoanele păgubite în Republica Moldova, pentru a compensa pagubele produse de către deținătorii de certificate de asigurare „Carte Verde” emise de către asigurătorii din străinătate.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Fondul de compensare are ca mijloace financiare contribuțiile asigurătorilor RCA licențiați să desfășoare activitate de asigurare obligatorie RCA externă, și anume:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"contribuția inițială, cu titlu de garanție, în caz de neonorare, în termenul stabilit, de către asigurătorul RCA a cărui licența a fost suspendată sau retrasă ori care se află în procedură de rezoluție/remediere financiară a obligațiilor privind plata despăgubirilor de asigurare obligatorie RCA externă sau în caz de neachitare a plăților ce rezultă din calitatea lui de membru al BNAA-ului. Soldul contribuției inițiale, cu dobânzile aferente, se restituie asigurătorului RCA în termen de 30 de zile din momentul intrării în vigoare a deciziei Băncii Naționale a Moldovei cu privire la transferul de portofoliu cu toate obligațiile de despăgubire sau în termen de 7 ani de la data retragerii licenței, dar nu înainte de lichidarea totală a pagubelor și de îndeplinirea tuturor obligațiilor de plată care derivă din vânzările anterioare a certificatelor de asigurare „Carte Verde”;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"contribuția suplimentară, cu titlu de garanție, constituită potrivit art. 37 alin. (6), pentru cazul prevăzut la lit. a). Soldul contribuției suplimentare, cu dobânzile aferente, se restituie asigurătorului RCA în termen de 30 de zile din momentul în care decizia organelor de conducere ale Consiliului Birourilor referitoare la revocarea sau la suspendarea cerinței privind garanția financiară externă devine executorie pentru BNAA, precum și în cazurile prevăzute la lit. a) din prezentul alineat;","lvl":2,"r":[[69,86,{"art":"37","al":"6"}],[113,120,{"lit":"a","art":"40","al":"2"}],[469,476,{"lit":"a","art":"40","al":"2"}]]},{"k":"lit","n":"c","id":"a2.lc","t":"contribuția lunară, destinată realizării obiectivelor Fondului de compensare, conform alin. (1);","lvl":2,"r":[[86,95,{"al":"1","art":"40"}]]},{"k":"lit","n":"d","id":"a2.ld","t":"contribuția specială primită de la asigurătorii RCA sub formă de împrumut, în funcție de necesitățile curente ale Fondului de compensare.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Sursa de acoperire a contribuțiilor prevăzute la alin. (2), cuantumul și termenul lor de achitare, modul de gestionare, utilizare și repartizare a mijloacelor financiare ale Fondului de compensare se stabilesc prin actele normative ale Băncii Naționale a Moldovei.","lvl":1,"r":[[49,58,{"al":"2","art":"40"}]]},{"k":"al","n":"4","id":"a4","t":"În cazul în care BNAA utilizează mijloace financiare ale Fondului de compensare pentru obiectivul prevăzut la alin. (1) lit. a), asigurătorii RCA, în al căror nume au fost utilizate aceste mijloace, au obligația să compenseze integral aceste cheltuieli.","lvl":1,"r":[[110,127,{"al":"1","lit":"a","art":"40"}]]},{"k":"al","n":"5","id":"a5","t":"BNAA are obligația de a ține o evidență a mijloacelor financiare primite, divizate pe tipuri de contribuții, și a cheltuielilor din Fondul de compensare, precum și de a investi disponibilitățile fondului menționat în instrumente financiare purtătoare de dobândă la bănci, în instrumente ale pieței monetare sau în valori mobiliare de stat.","lvl":1}]},{"id":"41","num":"41","title":"Competențele BNAA-ului privind furnizarea informațiilor","node":"n11","blocks":[{"k":"al","n":"1","id":"a1","t":"În vederea furnizării informațiilor despre accidente, BNAA are următoarele competențe:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"furnizează informația și actele solicitate de către birourile naționale, asigurătorii sau corespondenții din străinătate cu privire la asigurați, la asigurătorii RCA, la certificatele de asigurare „Carte Verde” (cum ar fi existența unui contract de asigurare pentru un anumit vehicul indicat la o anumită dată, confirmarea valabilității certificatului de asigurare „Carte Verde”, după caz), la vehiculul înregistrat în Republica Moldova, precum și la plăcile cu numerele de înmatriculare;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"oferă date privind reprezentantul de despăgubiri sau corespondentul din Republica Moldova al asigurătorului RCA din străinătate;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"acordă, la cererea persoanelor păgubite care prezintă un interes legitim, datele privind proprietarul și/sau utilizatorul de vehicul culpabil de producerea accidentului, informația despre vehiculul înregistrat în Republica Moldova, implicat în accident de vehicul produs în afara hotarelor acesteia, informația despre vehiculul înregistrat în străinătate, implicat în accident de vehicul pe teritoriul Republicii Moldova, precum și despre asigurările obligatorii RCA deținute de acestea, și dovada existenței interesului legitim care este în sarcina persoanei care face solicitarea.","lvl":2},{"k":"al","n":"2","id":"a2","t":"BNAA primește și/sau furnizează instituțiilor subordonate ale Ministerului Afacerilor Interne și Agenției Servicii Publice, instituțiilor cu atribuții de organizare și coordonare a activității de evidență și eliberare a certificatelor de înmatriculare și a plăcilor cu numere de înmatriculare datele privind accidentele produse și vehiculele pentru care au fost emise asigurări obligatorii RCA.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Furnizarea datelor cu caracter personal se face în conformitate cu prevederile legislației privind protecția datelor cu caracter personal, ce se referă la prelucrarea și libera circulație a acestor date.","lvl":1},{"k":"al","n":"4","id":"a4","t":"BNAA nu poate prelucra datele cu caracter personal la care are acces în scopuri altele decât cele prevăzute de prezenta lege.","lvl":1}]},{"id":"42","num":"42","title":"Evidența asigurărilor obligatorii RCA","node":"n12","blocks":[{"k":"al","n":"1","id":"a1","t":"Asigurătorul RCA ține evidența zilnică distinctă, în regim electronic, referitoare la asigurarea obligatorie RCA și prezintă un raport lunar și trimestrial în modul și în termenele stabilite de către Banca Națională a Moldovei.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Asigurătorul RCA înființează și ține zilnic, în regim electronic, registrul de evidență a contractelor de asigurare încheiate pentru asigurarea obligatorie RCA.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Asigurătorul RCA este obligat să prezinte Băncii Naționale a Moldovei și BNAA-ului, în modul stabilit, informațiile despre fiecare contract de asigurare obligatorie RCA încheiat.","lvl":1}]},{"id":"43","num":"43","title":"Controlul asigurării obligatorii RCA","node":"n12","blocks":[{"k":"al","n":"1","id":"a1","t":"Controalele sunt permise dacă acestea au un caracter nediscriminatoriu și se desfășoară în cadrul controalelor care nu urmăresc exclusiv verificarea asigurării.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Instituțiile subordonate ale Ministerului Afacerilor Interne se învestesc cu funcție de control asupra dețineri de către proprietarii și/sau utilizatorii de vehicule a asigurării obligatorii RCA.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Instituțiile subordonate ale Ministerului Afacerilor Interne vor exercita în punctele de trecere a frontierei de stat a Republicii Moldova funcția de control asupra:","lvl":1},{"k":"lit","n":"a","id":"a3.la","t":"deținerii, la intrarea în țară, de către proprietarii și/sau utilizatorii de vehicule înmatriculate în statele terțe a documentelor internaționale de asigurare, valabile în Republica Moldova;","lvl":2},{"k":"lit","n":"b","id":"a3.lb","t":"deținerii, la ieșirea din țară, de către proprietarii și/sau utilizatorii de vehicule înmatriculate în Republica Moldova a unuia dintre următoarele acte:","lvl":2},{"k":"dash","id":"d1","t":"certificatul de asigurare „Carte Verde” valabil pentru țara de destinație, eliberat de către asigurătorii RCA licențiați din Republica Moldova;","lvl":3},{"k":"dash","id":"d2","t":"documentul internațional de asigurare valabil pentru țara de destinație, emis sub garanția unui birou național din străinătate;","lvl":3},{"k":"dash","id":"d3","t":"alte documente de asigurare auto valabile pentru țara de destinație.","lvl":3},{"k":"al","n":"4","id":"a4","t":"Stațiile de inspecție tehnică autorizate efectuează inspecție tehnică periodică doar în cazul vehiculelor ai căror proprietari și/sau utilizatori dețin asigurare obligatorie RCA internă.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Entitățile menţionate la alin.(2)–(4) vor realiza funcţia de control, iar Comisia Națională a Pieței Financiare – atribuțiile prevăzute de prezenta lege, prin utilizarea Sistemului informațional automatizat de stat în domeniul asigurărilor obligatorii RCA, în baza acordurilor de schimb de informaţii cu Banca Națională a Moldovei.","lvl":1,"r":[[25,37,{"al":"2","al2":"4","art":"43"}]]},{"k":"al","n":"6","id":"a6","t":"La înscrierea în circulație a vehiculului, la efectuarea modificărilor în certificatul de înmatriculare a unui vehicul și a inspecțiilor tehnice periodice se prezintă dovada asigurării obligatorii RCA interne, în condițiile prezentei legi.","lvl":1},{"k":"al","n":"7","id":"a7","t":"Exploatarea pe teritoriul Republicii Moldova a vehiculului fără asigurare obligatorie RCA internă sau, după caz, fără document internațional de asigurare valabil în Republica Moldova se sancționează în conformitate cu Codul contravențional.","lvl":1,"r":[[218,239,{"a":"cod:contraventional","whole":true}]]},{"k":"al","n":"8","id":"a8","t":"Confecționarea, deținerea, vânzarea sau folosirea polițelor de asigurare obligatorie RCA și a certificatelor de asigurare „Carte Verde” false ori neautorizate și/sau inducerea în eroare în privința naturii, calităților substanțiale ale materialelor, ale părților componente și ale pieselor înlocuitoare de către unitățile de reparații care recondiționează vehicule avariate constituie o infracțiune care se sancționează în conformitate cu Codul penal.","lvl":1,"r":[[439,450,{"a":"cod:penal","whole":true}]]}]},{"id":"44","num":"44","title":"Dispoziții tranzitorii","node":"n13","blocks":[{"k":"al","n":"1","id":"a1","t":"Actele și faptele juridice încheiate sau, după caz, săvârșite ori produse înainte de intrarea în vigoare a prezentei legi nu pot genera alte efecte juridice decât cele prevăzute de legislaţia în vigoare la data încheierii sau, după caz, a săvârșirii ori producerii lor.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Prezenta lege se aplică tuturor contractelor de asigurare obligatorie RCA emise după data intrării în vigoare a acesteia și în legătură cu toate pagubele care se despăgubesc în baza acestora.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Asigurătorii RCA care, la data publicării prezentei legi în Monitorul Oficial al Republicii Moldova, dețin licență pentru desfășurarea activității de asigurare obligatorie RCA își vor conforma activitatea până la data intrării în vigoare a prezentei legi.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Actele normative adoptate de către Comisia Națională a Pieței Financiare în temeiul Legii nr.414/2006 cu privire la asigurarea obligatorie de răspundere civilă pentru pagube produse de autovehicule, cu modificările ulterioare, se aplică în continuare, în măsura în care nu contravin prezentei legi, până la abrogarea expresă a acesteia.","lvl":1,"r":[[84,101,{"a":"lege:414/2006","whole":true}]]},{"k":"al","n":"5","id":"a5","t":"Până la 1 iulie 2023, atribuțiile autorității de supraveghere, în sensul prezentei legi, vor fi exercitate de către Comisia Națională a Pieței Financiare.","lvl":1},{"k":"al","n":"6","id":"a6","t":"În termen de 3 ani de la data intrării în vigoare a prezentei legi, până la implementarea sistemelor informaționale automatizate de evaluare în domeniul auto, prin derogare de la prevederile art. 25 alin. (12), în cazul în care despăgubirea de asigurare se solicită în numerar sau prin virament în contul bancar al persoanei păgubite, indiferent de vechimea vehiculului și parcursul acestuia, cuantumul despăgubirii de asigurare se stabilește luând în calcul prețurile medii practicate de minimum trei unități de reparații acceptate de către părți pentru manoperă și pentru materialele aferente reparației și/sau înlocuirii părților componente și a pieselor avariate, precum și pentru părțile componente și piesele noi fabricate în bază de licență sau originale foste în folosință care sunt disponibile pe piața autohtonă. În cazul în care părțile componente și piesele noi fabricate în bază de licență sau cele originale foste în folosință nu sunt disponibile pe piața autohtonă, costul reparației pentru vehicule se va determina ținând cont de sistemele informaționale automatizate de evaluare în domeniul auto, ce corespund cerințelor stabilite în actele normative ale Comisiei Naționale a Pieței Financiare pentru prețurile materialelor, ale părților componente și ale pieselor înlocuitoare. Valoarea tarifului orei de manoperă este stabilită prin actul normativ al Comisiei Naționale a Pieței Financiare, în condițiile aplicabile Republicii Moldova.","lvl":1,"r":[[191,209,{"art":"25","al":"12"}]]},{"k":"note","t":"[Art.44 al.(6) modificat prin LP189 din 10.07.25, MO502-505/25.09.25 art.652; în vigoare 25.10.25]","id":"n1","lvl":0}]},{"id":"45","num":"45","title":"Dispoziții finale","node":"n13","blocks":[{"k":"al","n":"1","id":"a1","t":"Prezenta lege intră în vigoare la 1 aprilie 2023.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Guvernul, în comun cu autoritatea de supraveghere, până la data intrării în vigoare a prezentei legi, va prezenta Parlamentului propuneri privind aducerea legislației în vigoare în concordanță cu prezenta lege.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Banca Națională a Moldovei și Comisia Națională a Pieței Financiare, în termen de 6 luni de la data intrării în vigoare a prezentei legi, vor elabora şi vor adopta actele lor normative necesare pentru executarea prezentei legi.","lvl":1},{"k":"al","n":"4","id":"a4","t":"La data intrării în vigoare a prezentei legi se abrogă Legea nr. 414/2006 cu privire la asigurarea obligatorie de răspundere civilă pentru pagube produse de autovehicule.","lvl":1,"r":[[55,73,{"a":"lege:414/2006","whole":true}]]}]}],"annexes":[]};
